INSERT INTO public.recipes (id, title, cuisine, budget_tier, goals, minutes, equipment_tags, servings, steps, macros, cost_per_serving, cost_full_pack, image_url, emoji, gradient_seed) VALUES
(1, 'Kanda Poha with Roasted Peanuts', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Place 90g thick poha in a colander and rinse gently under slow running water for 20 seconds; drain completely and let rest 5 minutes.","timer_seconds":300,"tip":"⚠️ Where this goes wrong: Rinsing poha for too long or soaking it in standing water turns it into soggy mush. A quick 20-second rinse in a colander is all it takes."},{"text":"Finely chop 1 medium onion (60g) and slice 1 green chilli into thin rounds."},{"text":"Heat 10ml cooking oil in a pan on medium induction heat (level 4 / 600W) for 45 seconds.","timer_seconds":45},{"text":"Add 1/2 tsp mustard seeds and sliced green chilli; sauté for 30 seconds until seeds begin to crackle.","timer_seconds":30},{"text":"Add the chopped onions and sauté for 2.5 minutes until translucent and soft.","timer_seconds":150},{"text":"Lower heat to minimum, add 1/2 tsp turmeric powder, 1/2 tsp salt, and the drained poha. Gently toss with a flat spatula for 2 minutes until evenly yellow.","timer_seconds":120},{"text":"Turn off heat, cover pan with lid for 1 minute to let residual steam plump the flakes, then squeeze 1/2 fresh lemon.","timer_seconds":60},{"text":"In 1 tsp oil, fry 25g raw peanuts for 2 minutes until crunchy and golden brown; scatter over the warm poha.","timer_seconds":120}]'::jsonb, '{"kcal":612,"protein":14.9,"carbs":84,"fats":25.6,"fiber":7.6}'::jsonb, 20.6, 347, 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=600&q=80', '🍚', 1),
(2, 'Kanda Poha with Boiled Egg Slices', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 14, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Place 90g thick poha in a colander and rinse gently under slow running water for 20 seconds; drain completely and let rest 5 minutes.","timer_seconds":300,"tip":"⚠️ Where this goes wrong: Rinsing poha for too long or soaking it in standing water turns it into soggy mush. A quick 20-second rinse in a colander is all it takes."},{"text":"Finely chop 1 medium onion (60g) and slice 1 green chilli into thin rounds."},{"text":"Heat 10ml cooking oil in a pan on medium induction heat (level 4 / 600W) for 45 seconds.","timer_seconds":45},{"text":"Add 1/2 tsp mustard seeds and sliced green chilli; sauté for 30 seconds until seeds begin to crackle.","timer_seconds":30},{"text":"Add the chopped onions and sauté for 2.5 minutes until translucent and soft.","timer_seconds":150},{"text":"Lower heat to minimum, add 1/2 tsp turmeric powder, 1/2 tsp salt, and the drained poha. Gently toss with a flat spatula for 2 minutes until evenly yellow.","timer_seconds":120},{"text":"Turn off heat, cover pan with lid for 1 minute to let residual steam plump the flakes, then squeeze 1/2 fresh lemon.","timer_seconds":60},{"text":"Hard-boil 1 egg for 8 minutes, peel, slice into neat rounds, and arrange over the poha with black pepper.","timer_seconds":480}]'::jsonb, '{"kcal":542,"protein":14.7,"carbs":80.4,"fats":18.3,"fiber":5.5}'::jsonb, 24.2, 359, 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=600&q=80', '🍚', 2),
(3, 'Kanda Poha with Fresh Dhaniya & Lemon', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Place 90g thick poha in a colander and rinse gently under slow running water for 20 seconds; drain completely and let rest 5 minutes.","timer_seconds":300,"tip":"⚠️ Where this goes wrong: Rinsing poha for too long or soaking it in standing water turns it into soggy mush. A quick 20-second rinse in a colander is all it takes."},{"text":"Finely chop 1 medium onion (60g) and slice 1 green chilli into thin rounds."},{"text":"Heat 10ml cooking oil in a pan on medium induction heat (level 4 / 600W) for 45 seconds.","timer_seconds":45},{"text":"Add 1/2 tsp mustard seeds and sliced green chilli; sauté for 30 seconds until seeds begin to crackle.","timer_seconds":30},{"text":"Add the chopped onions and sauté for 2.5 minutes until translucent and soft.","timer_seconds":150},{"text":"Lower heat to minimum, add 1/2 tsp turmeric powder, 1/2 tsp salt, and the drained poha. Gently toss with a flat spatula for 2 minutes until evenly yellow.","timer_seconds":120},{"text":"Turn off heat, cover pan with lid for 1 minute to let residual steam plump the flakes, then squeeze 1/2 fresh lemon.","timer_seconds":60},{"text":"Finely mince a generous 15g fresh coriander leaves and squeeze an extra half lemon for bright zesty punch."}]'::jsonb, '{"kcal":481,"protein":9,"carbs":82.8,"fats":13.5,"fiber":6.6}'::jsonb, 18.3, 307, 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=600&q=80', '🍚', 3),
(4, 'Kanda Poha with Crispy Potato Cubes', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 13, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Place 90g thick poha in a colander and rinse gently under slow running water for 20 seconds; drain completely and let rest 5 minutes.","timer_seconds":300,"tip":"⚠️ Where this goes wrong: Rinsing poha for too long or soaking it in standing water turns it into soggy mush. A quick 20-second rinse in a colander is all it takes."},{"text":"Finely chop 1 medium onion (60g) and slice 1 green chilli into thin rounds."},{"text":"Heat 10ml cooking oil in a pan on medium induction heat (level 4 / 600W) for 45 seconds.","timer_seconds":45},{"text":"Add 1/2 tsp mustard seeds and sliced green chilli; sauté for 30 seconds until seeds begin to crackle.","timer_seconds":30},{"text":"Add the chopped onions and sauté for 2.5 minutes until translucent and soft.","timer_seconds":150},{"text":"Lower heat to minimum, add 1/2 tsp turmeric powder, 1/2 tsp salt, and the drained poha. Gently toss with a flat spatula for 2 minutes until evenly yellow.","timer_seconds":120},{"text":"Turn off heat, cover pan with lid for 1 minute to let residual steam plump the flakes, then squeeze 1/2 fresh lemon.","timer_seconds":60},{"text":"Peel and dice 80g potato into 5mm mini cubes; shallow fry in pan for 3.5 minutes until crispy before mixing with onions.","timer_seconds":210}]'::jsonb, '{"kcal":532,"protein":10,"carbs":94,"fats":13.4,"fiber":7.3}'::jsonb, 18.1, 339, 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=600&q=80', '🍚', 4),
(5, 'Kanda Poha with Grated Paneer', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Place 90g thick poha in a colander and rinse gently under slow running water for 20 seconds; drain completely and let rest 5 minutes.","timer_seconds":300,"tip":"⚠️ Where this goes wrong: Rinsing poha for too long or soaking it in standing water turns it into soggy mush. A quick 20-second rinse in a colander is all it takes."},{"text":"Finely chop 1 medium onion (60g) and slice 1 green chilli into thin rounds."},{"text":"Heat 10ml cooking oil in a pan on medium induction heat (level 4 / 600W) for 45 seconds.","timer_seconds":45},{"text":"Add 1/2 tsp mustard seeds and sliced green chilli; sauté for 30 seconds until seeds begin to crackle.","timer_seconds":30},{"text":"Add the chopped onions and sauté for 2.5 minutes until translucent and soft.","timer_seconds":150},{"text":"Lower heat to minimum, add 1/2 tsp turmeric powder, 1/2 tsp salt, and the drained poha. Gently toss with a flat spatula for 2 minutes until evenly yellow.","timer_seconds":120},{"text":"Turn off heat, cover pan with lid for 1 minute to let residual steam plump the flakes, then squeeze 1/2 fresh lemon.","timer_seconds":60},{"text":"Grate 50g fresh paneer evenly across the steaming poha; let it soften gently in the steam for 30 seconds.","timer_seconds":30}]'::jsonb, '{"kcal":615,"protein":17.4,"carbs":81.5,"fats":24.3,"fiber":5.5}'::jsonb, 36.8, 392, 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=600&q=80', '🍚', 5),
(6, 'Kanda Poha with Sautéed Sweet Corn', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Place 90g thick poha in a colander and rinse gently under slow running water for 20 seconds; drain completely and let rest 5 minutes.","timer_seconds":300,"tip":"⚠️ Where this goes wrong: Rinsing poha for too long or soaking it in standing water turns it into soggy mush. A quick 20-second rinse in a colander is all it takes."},{"text":"Finely chop 1 medium onion (60g) and slice 1 green chilli into thin rounds."},{"text":"Heat 10ml cooking oil in a pan on medium induction heat (level 4 / 600W) for 45 seconds.","timer_seconds":45},{"text":"Add 1/2 tsp mustard seeds and sliced green chilli; sauté for 30 seconds until seeds begin to crackle.","timer_seconds":30},{"text":"Add the chopped onions and sauté for 2.5 minutes until translucent and soft.","timer_seconds":150},{"text":"Lower heat to minimum, add 1/2 tsp turmeric powder, 1/2 tsp salt, and the drained poha. Gently toss with a flat spatula for 2 minutes until evenly yellow.","timer_seconds":120},{"text":"Turn off heat, cover pan with lid for 1 minute to let residual steam plump the flakes, then squeeze 1/2 fresh lemon.","timer_seconds":60},{"text":"Add 40g sweet corn kernels along with the onions and sauté for 2 minutes until plump and sweet.","timer_seconds":120}]'::jsonb, '{"kcal":504,"protein":9.7,"carbs":87.6,"fats":13.8,"fiber":6.6}'::jsonb, 22, 347, 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=600&q=80', '🍚', 6),
(7, 'Kanda Poha with Butter Tadka', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Place 90g thick poha in a colander and rinse gently under slow running water for 20 seconds; drain completely and let rest 5 minutes.","timer_seconds":300,"tip":"⚠️ Where this goes wrong: Rinsing poha for too long or soaking it in standing water turns it into soggy mush. A quick 20-second rinse in a colander is all it takes."},{"text":"Finely chop 1 medium onion (60g) and slice 1 green chilli into thin rounds."},{"text":"Heat 10ml cooking oil in a pan on medium induction heat (level 4 / 600W) for 45 seconds.","timer_seconds":45},{"text":"Add 1/2 tsp mustard seeds and sliced green chilli; sauté for 30 seconds until seeds begin to crackle.","timer_seconds":30},{"text":"Add the chopped onions and sauté for 2.5 minutes until translucent and soft.","timer_seconds":150},{"text":"Lower heat to minimum, add 1/2 tsp turmeric powder, 1/2 tsp salt, and the drained poha. Gently toss with a flat spatula for 2 minutes until evenly yellow.","timer_seconds":120},{"text":"Turn off heat, cover pan with lid for 1 minute to let residual steam plump the flakes, then squeeze 1/2 fresh lemon.","timer_seconds":60},{"text":"Melt 10g salted butter in a small ladle until foaming, then drizzle the golden butter sizzle over the plated poha.","timer_seconds":45}]'::jsonb, '{"kcal":542,"protein":8.5,"carbs":80,"fats":21.4,"fiber":5.5}'::jsonb, 21.2, 363, 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=600&q=80', '🍚', 7),
(8, 'Moong Dal Khichdi with Desi Ghee Jeera Tadka', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 15, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Measure 60g rice and 60g moong dal together; wash 3 times until water runs mostly clear, then drain.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Skimping on water leaves hard, chalky lentils. Always maintain a generous 1:4 water ratio so the dal fully breaks down into creamy comfort porridge."},{"text":"In your kettle or deep pot, melt 10ml desi ghee on medium heat for 45 seconds.","timer_seconds":45},{"text":"Add 1 tsp cumin seeds and 1 tsp finely grated ginger; sauté for 30 seconds until warm and fragrant.","timer_seconds":30},{"text":"Tip in the drained rice-dal mix, 1/2 tsp turmeric powder, and 3/4 tsp salt. Stir gently for 1 minute to toast in ghee.","timer_seconds":60},{"text":"Pour in 500ml water. Cover with lid loosely and simmer on low for 12 minutes until grains are completely soft.","timer_seconds":720},{"text":"Beat lightly with the back of a ladle to achieve that classic creamy, soupy consistency.","timer_seconds":30},{"text":"Heat an extra 10ml desi ghee with 1/2 tsp cumin seeds until dark golden, and pour the crackling tadka right on top.","timer_seconds":45}]'::jsonb, '{"kcal":642,"protein":20.1,"carbs":89.3,"fats":22.9,"fiber":11.6}'::jsonb, 32, 376, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?auto=format&fit=crop&w=600&q=80', '🍲', 8),
(9, 'Moong Dal Khichdi with Fresh Curd', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 15, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Measure 60g rice and 60g moong dal together; wash 3 times until water runs mostly clear, then drain.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Skimping on water leaves hard, chalky lentils. Always maintain a generous 1:4 water ratio so the dal fully breaks down into creamy comfort porridge."},{"text":"In your kettle or deep pot, melt 10ml desi ghee on medium heat for 45 seconds.","timer_seconds":45},{"text":"Add 1 tsp cumin seeds and 1 tsp finely grated ginger; sauté for 30 seconds until warm and fragrant.","timer_seconds":30},{"text":"Tip in the drained rice-dal mix, 1/2 tsp turmeric powder, and 3/4 tsp salt. Stir gently for 1 minute to toast in ghee.","timer_seconds":60},{"text":"Pour in 500ml water. Cover with lid loosely and simmer on low for 12 minutes until grains are completely soft.","timer_seconds":720},{"text":"Beat lightly with the back of a ladle to achieve that classic creamy, soupy consistency.","timer_seconds":30},{"text":"Ladle 80g cold, fresh creamy curd (dahi) on the side of the bowl for that soothing hot-and-cold contrast."}]'::jsonb, '{"kcal":588,"protein":22.4,"carbs":91.7,"fats":14.6,"fiber":11.3}'::jsonb, 30.1, 411, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?auto=format&fit=crop&w=600&q=80', '🍲', 9),
(10, 'Moong Dal Khichdi with Sautéed Spinach', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 15, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Measure 60g rice and 60g moong dal together; wash 3 times until water runs mostly clear, then drain.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Skimping on water leaves hard, chalky lentils. Always maintain a generous 1:4 water ratio so the dal fully breaks down into creamy comfort porridge."},{"text":"In your kettle or deep pot, melt 10ml desi ghee on medium heat for 45 seconds.","timer_seconds":45},{"text":"Add 1 tsp cumin seeds and 1 tsp finely grated ginger; sauté for 30 seconds until warm and fragrant.","timer_seconds":30},{"text":"Tip in the drained rice-dal mix, 1/2 tsp turmeric powder, and 3/4 tsp salt. Stir gently for 1 minute to toast in ghee.","timer_seconds":60},{"text":"Pour in 500ml water. Cover with lid loosely and simmer on low for 12 minutes until grains are completely soft.","timer_seconds":720},{"text":"Beat lightly with the back of a ladle to achieve that classic creamy, soupy consistency.","timer_seconds":30},{"text":"Roughly chop 50g fresh spinach and 1 clove garlic; stir directly into the hot khichdi for 90 seconds until wilted.","timer_seconds":90}]'::jsonb, '{"kcal":559,"protein":21.3,"carbs":91.4,"fats":12.4,"fiber":12.5}'::jsonb, 29.4, 426, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?auto=format&fit=crop&w=600&q=80', '🍲', 10),
(11, 'Moong Dal Khichdi with Crispy Fried Onions', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 15, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Measure 60g rice and 60g moong dal together; wash 3 times until water runs mostly clear, then drain.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Skimping on water leaves hard, chalky lentils. Always maintain a generous 1:4 water ratio so the dal fully breaks down into creamy comfort porridge."},{"text":"In your kettle or deep pot, melt 10ml desi ghee on medium heat for 45 seconds.","timer_seconds":45},{"text":"Add 1 tsp cumin seeds and 1 tsp finely grated ginger; sauté for 30 seconds until warm and fragrant.","timer_seconds":30},{"text":"Tip in the drained rice-dal mix, 1/2 tsp turmeric powder, and 3/4 tsp salt. Stir gently for 1 minute to toast in ghee.","timer_seconds":60},{"text":"Pour in 500ml water. Cover with lid loosely and simmer on low for 12 minutes until grains are completely soft.","timer_seconds":720},{"text":"Beat lightly with the back of a ladle to achieve that classic creamy, soupy consistency.","timer_seconds":30},{"text":"Thinly slice 40g onion and shallow fry in 1 tsp oil for 3 minutes until deep caramel brown; scatter over the bowl.","timer_seconds":180}]'::jsonb, '{"kcal":600,"protein":20,"carbs":91.7,"fats":17.3,"fiber":12}'::jsonb, 25.3, 544, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?auto=format&fit=crop&w=600&q=80', '🍲', 11),
(12, 'Moong Dal Khichdi with Aloo Fry', 'Indian', 'broke', ARRAY['muscle-gain'], 18, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Measure 60g rice and 60g moong dal together; wash 3 times until water runs mostly clear, then drain.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Skimping on water leaves hard, chalky lentils. Always maintain a generous 1:4 water ratio so the dal fully breaks down into creamy comfort porridge."},{"text":"In your kettle or deep pot, melt 10ml desi ghee on medium heat for 45 seconds.","timer_seconds":45},{"text":"Add 1 tsp cumin seeds and 1 tsp finely grated ginger; sauté for 30 seconds until warm and fragrant.","timer_seconds":30},{"text":"Tip in the drained rice-dal mix, 1/2 tsp turmeric powder, and 3/4 tsp salt. Stir gently for 1 minute to toast in ghee.","timer_seconds":60},{"text":"Pour in 500ml water. Cover with lid loosely and simmer on low for 12 minutes until grains are completely soft.","timer_seconds":720},{"text":"Beat lightly with the back of a ladle to achieve that classic creamy, soupy consistency.","timer_seconds":30},{"text":"Dice 70g potato into cubes, toss with 1/4 tsp red chilli powder and salt, pan-fry for 4 minutes until crisp-edged.","timer_seconds":240}]'::jsonb, '{"kcal":600,"protein":21.2,"carbs":101.2,"fats":12.6,"fiber":13.5}'::jsonb, 26.1, 442, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?auto=format&fit=crop&w=600&q=80', '🍲', 12),
(13, 'Moong Dal Khichdi with Butter & Black Pepper', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 15, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Measure 60g rice and 60g moong dal together; wash 3 times until water runs mostly clear, then drain.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Skimping on water leaves hard, chalky lentils. Always maintain a generous 1:4 water ratio so the dal fully breaks down into creamy comfort porridge."},{"text":"In your kettle or deep pot, melt 10ml desi ghee on medium heat for 45 seconds.","timer_seconds":45},{"text":"Add 1 tsp cumin seeds and 1 tsp finely grated ginger; sauté for 30 seconds until warm and fragrant.","timer_seconds":30},{"text":"Tip in the drained rice-dal mix, 1/2 tsp turmeric powder, and 3/4 tsp salt. Stir gently for 1 minute to toast in ghee.","timer_seconds":60},{"text":"Pour in 500ml water. Cover with lid loosely and simmer on low for 12 minutes until grains are completely soft.","timer_seconds":720},{"text":"Beat lightly with the back of a ladle to achieve that classic creamy, soupy consistency.","timer_seconds":30},{"text":"Drop 10g cold salted butter in the center of the steaming bowl and crack coarse black pepper over it."}]'::jsonb, '{"kcal":612,"protein":19.6,"carbs":88,"fats":20.3,"fiber":11.3}'::jsonb, 28.7, 432, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?auto=format&fit=crop&w=600&q=80', '🍲', 13),
(14, 'Moong Dal Khichdi with Soft Boiled Egg', 'Indian', 'broke', ARRAY['high-protein','muscle-gain'], 18, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Measure 60g rice and 60g moong dal together; wash 3 times until water runs mostly clear, then drain.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Skimping on water leaves hard, chalky lentils. Always maintain a generous 1:4 water ratio so the dal fully breaks down into creamy comfort porridge."},{"text":"In your kettle or deep pot, melt 10ml desi ghee on medium heat for 45 seconds.","timer_seconds":45},{"text":"Add 1 tsp cumin seeds and 1 tsp finely grated ginger; sauté for 30 seconds until warm and fragrant.","timer_seconds":30},{"text":"Tip in the drained rice-dal mix, 1/2 tsp turmeric powder, and 3/4 tsp salt. Stir gently for 1 minute to toast in ghee.","timer_seconds":60},{"text":"Pour in 500ml water. Cover with lid loosely and simmer on low for 12 minutes until grains are completely soft.","timer_seconds":720},{"text":"Beat lightly with the back of a ladle to achieve that classic creamy, soupy consistency.","timer_seconds":30},{"text":"Boil 1 egg for 6.5 minutes for a jammy yolk, peel, halve, and nestle gently into the hot khichdi.","timer_seconds":390}]'::jsonb, '{"kcal":612,"protein":25.9,"carbs":88.4,"fats":17.2,"fiber":11.3}'::jsonb, 31.8, 428, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?auto=format&fit=crop&w=600&q=80', '🍲', 14),
(15, 'Egg Bhurji with Toasted Butter Pav', 'Indian', 'broke', ARRAY['15-min','muscle-gain'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Finely dice 1 small onion (50g), 1 small tomato (50g), and 1 green chilli.","tip":"⚠️ Where this goes wrong: Blasting high heat while scrambling cooks out moisture and makes eggs tough and dry. Turn heat down and pull eggs off while still glossy and slightly wet."},{"text":"Crack 2 fresh eggs into a small bowl, add 1/3 tsp salt, and whisk briskly with a fork for 30 seconds.","timer_seconds":30},{"text":"Melt 10g butter in a frying pan over medium heat (600W) until sizzling.","timer_seconds":40},{"text":"Add diced onions and green chilli; sauté for 2 minutes until translucent.","timer_seconds":120},{"text":"Add chopped tomatoes, 1/4 tsp turmeric, and 1/4 tsp garam masala; cook for 2 minutes, mashing tomatoes with spatula.","timer_seconds":120},{"text":"Reduce heat to low, pour in whisked eggs, and scramble gently with circular motions for 90 seconds until soft curds form.","timer_seconds":90},{"text":"Remove from heat while eggs are still tender and glossy; stir in chopped fresh coriander.","timer_seconds":15},{"text":"Slit 2 pav buns horizontally, butter the pan, and toast both sides for 60 seconds until crusty and golden.","timer_seconds":60}]'::jsonb, '{"kcal":495,"protein":19.9,"carbs":40.4,"fats":28.9,"fiber":4.5}'::jsonb, 45.4, 314, 'https://images.unsplash.com/photo-1550547660-d9450f859349?auto=format&fit=crop&w=600&q=80', '🍳', 15),
