(20, 'Egg Bhurji with Roasted Cumin Butter', 'Indian', 'broke', ARRAY['15-min','fat-loss'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Finely dice 1 small onion (50g), 1 small tomato (50g), and 1 green chilli.","tip":"⚠️ Where this goes wrong: Blasting high heat while scrambling cooks out moisture and makes eggs tough and dry. Turn heat down and pull eggs off while still glossy and slightly wet."},{"text":"Crack 2 fresh eggs into a small bowl, add 1/3 tsp salt, and whisk briskly with a fork for 30 seconds.","timer_seconds":30},{"text":"Melt 10g butter in a frying pan over medium heat (600W) until sizzling.","timer_seconds":40},{"text":"Add diced onions and green chilli; sauté for 2 minutes until translucent.","timer_seconds":120},{"text":"Add chopped tomatoes, 1/4 tsp turmeric, and 1/4 tsp garam masala; cook for 2 minutes, mashing tomatoes with spatula.","timer_seconds":120},{"text":"Reduce heat to low, pour in whisked eggs, and scramble gently with circular motions for 90 seconds until soft curds form.","timer_seconds":90},{"text":"Remove from heat while eggs are still tender and glossy; stir in chopped fresh coriander.","timer_seconds":15},{"text":"Warm 10g butter with 1/2 tsp cumin seeds in a small spoon until fragrant, then swirl across the eggs.","timer_seconds":40}]'::jsonb, '{"kcal":342,"protein":14.9,"carbs":11.3,"fats":27.3,"fiber":2.9}'::jsonb, 36.2, 312, 'https://images.unsplash.com/photo-1550547660-d9450f859349?auto=format&fit=crop&w=600&q=80', '🍳', 20),
(21, 'Egg Bhurji with Sautéed Mushrooms', 'Indian', 'broke', ARRAY['15-min','fat-loss'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Finely dice 1 small onion (50g), 1 small tomato (50g), and 1 green chilli.","tip":"⚠️ Where this goes wrong: Blasting high heat while scrambling cooks out moisture and makes eggs tough and dry. Turn heat down and pull eggs off while still glossy and slightly wet."},{"text":"Crack 2 fresh eggs into a small bowl, add 1/3 tsp salt, and whisk briskly with a fork for 30 seconds.","timer_seconds":30},{"text":"Melt 10g butter in a frying pan over medium heat (600W) until sizzling.","timer_seconds":40},{"text":"Add diced onions and green chilli; sauté for 2 minutes until translucent.","timer_seconds":120},{"text":"Add chopped tomatoes, 1/4 tsp turmeric, and 1/4 tsp garam masala; cook for 2 minutes, mashing tomatoes with spatula.","timer_seconds":120},{"text":"Reduce heat to low, pour in whisked eggs, and scramble gently with circular motions for 90 seconds until soft curds form.","timer_seconds":90},{"text":"Remove from heat while eggs are still tender and glossy; stir in chopped fresh coriander.","timer_seconds":15},{"text":"Slice 60g button mushrooms and sauté in butter for 2.5 minutes until browned before adding the eggs.","timer_seconds":150}]'::jsonb, '{"kcal":276,"protein":16.3,"carbs":12.4,"fats":19,"fiber":3.3}'::jsonb, 49.3, 339, 'https://images.unsplash.com/photo-1550547660-d9450f859349?auto=format&fit=crop&w=600&q=80', '🍳', 21),
(22, 'Soya Keema Bhurji with Toasted Pav', 'Indian', 'broke', ARRAY['15-min','high-protein','muscle-gain'], 15, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Place 55g soya chunks in a bowl, pour 300ml boiling water, and soak for 7 minutes until spongy.","timer_seconds":420,"tip":"⚠️ Where this goes wrong: Not squeezing the soaked soya chunks leaves a soggy, raw flavor. Press firmly in a clean cloth or fist until completely dry before chopping."},{"text":"Drain soya in a strainer, rinse with cold water, squeeze out all excess moisture firmly, and finely chop to coarse mince."},{"text":"Heat 10ml cooking oil in a pan on medium heat. Add 1 tsp minced ginger and 1 tsp minced garlic; sauté 30 seconds.","timer_seconds":30},{"text":"Add 1 finely chopped onion; cook for 3 minutes until light golden brown.","timer_seconds":180},{"text":"Add 1 chopped tomato, 1/2 tsp red chilli powder, 1/2 tsp garam masala, and 1/2 tsp salt; cook 2 minutes until saucy.","timer_seconds":120},{"text":"Toss in the minced soya with 3 tbsp water. Cover and simmer on low heat for 4 minutes so soya absorbs the spices.","timer_seconds":240},{"text":"Butter and toast 2 soft pav buns on a hot tawa for 60 seconds until crusty and golden.","timer_seconds":60}]'::jsonb, '{"kcal":564,"protein":36.6,"carbs":62,"fats":19.9,"fiber":12.7}'::jsonb, 38.9, 461, 'https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=600&q=80', '🥘', 22),
(23, 'Soya Keema Bhurji with Fresh Curd & Mint', 'Indian', 'broke', ARRAY['15-min','high-protein','fat-loss'], 15, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Place 55g soya chunks in a bowl, pour 300ml boiling water, and soak for 7 minutes until spongy.","timer_seconds":420,"tip":"⚠️ Where this goes wrong: Not squeezing the soaked soya chunks leaves a soggy, raw flavor. Press firmly in a clean cloth or fist until completely dry before chopping."},{"text":"Drain soya in a strainer, rinse with cold water, squeeze out all excess moisture firmly, and finely chop to coarse mince."},{"text":"Heat 10ml cooking oil in a pan on medium heat. Add 1 tsp minced ginger and 1 tsp minced garlic; sauté 30 seconds.","timer_seconds":30},{"text":"Add 1 finely chopped onion; cook for 3 minutes until light golden brown.","timer_seconds":180},{"text":"Add 1 chopped tomato, 1/2 tsp red chilli powder, 1/2 tsp garam masala, and 1/2 tsp salt; cook 2 minutes until saucy.","timer_seconds":120},{"text":"Toss in the minced soya with 3 tbsp water. Cover and simmer on low heat for 4 minutes so soya absorbs the spices.","timer_seconds":240},{"text":"Serve alongside 60g chilled thick curd whisked with a pinch of salt and crushed mint leaves."}]'::jsonb, '{"kcal":383,"protein":33.2,"carbs":34.8,"fats":13.2,"fiber":10.9}'::jsonb, 29.6, 400, 'https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=600&q=80', '🥘', 23),
(24, 'Soya Keema Bhurji with Sautéed Capsicum', 'Indian', 'broke', ARRAY['15-min','high-protein','fat-loss'], 15, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Place 55g soya chunks in a bowl, pour 300ml boiling water, and soak for 7 minutes until spongy.","timer_seconds":420,"tip":"⚠️ Where this goes wrong: Not squeezing the soaked soya chunks leaves a soggy, raw flavor. Press firmly in a clean cloth or fist until completely dry before chopping."},{"text":"Drain soya in a strainer, rinse with cold water, squeeze out all excess moisture firmly, and finely chop to coarse mince."},{"text":"Heat 10ml cooking oil in a pan on medium heat. Add 1 tsp minced ginger and 1 tsp minced garlic; sauté 30 seconds.","timer_seconds":30},{"text":"Add 1 finely chopped onion; cook for 3 minutes until light golden brown.","timer_seconds":180},{"text":"Add 1 chopped tomato, 1/2 tsp red chilli powder, 1/2 tsp garam masala, and 1/2 tsp salt; cook 2 minutes until saucy.","timer_seconds":120},{"text":"Toss in the minced soya with 3 tbsp water. Cover and simmer on low heat for 4 minutes so soya absorbs the spices.","timer_seconds":240},{"text":"Dice 40g green bell pepper and toss into the pan for the final 2 minutes for crunch and aroma.","timer_seconds":120}]'::jsonb, '{"kcal":357,"protein":31.5,"carbs":34.4,"fats":11.5,"fiber":11.7}'::jsonb, 29.5, 397, 'https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=600&q=80', '🥘', 24),
