(27, 'Soya Keema Bhurji with Melting Processed Cheese', 'Indian', 'broke', ARRAY['15-min','high-protein','fat-loss'], 15, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Place 55g soya chunks in a bowl, pour 300ml boiling water, and soak for 7 minutes until spongy.","timer_seconds":420,"tip":"⚠️ Where this goes wrong: Not squeezing the soaked soya chunks leaves a soggy, raw flavor. Press firmly in a clean cloth or fist until completely dry before chopping."},{"text":"Drain soya in a strainer, rinse with cold water, squeeze out all excess moisture firmly, and finely chop to coarse mince."},{"text":"Heat 10ml cooking oil in a pan on medium heat. Add 1 tsp minced ginger and 1 tsp minced garlic; sauté 30 seconds.","timer_seconds":30},{"text":"Add 1 finely chopped onion; cook for 3 minutes until light golden brown.","timer_seconds":180},{"text":"Add 1 chopped tomato, 1/2 tsp red chilli powder, 1/2 tsp garam masala, and 1/2 tsp salt; cook 2 minutes until saucy.","timer_seconds":120},{"text":"Toss in the minced soya with 3 tbsp water. Cover and simmer on low heat for 4 minutes so soya absorbs the spices.","timer_seconds":240},{"text":"Place 1 processed cheese slice over the steaming keema, cover pan for 45 seconds until molten.","timer_seconds":45}]'::jsonb, '{"kcal":412,"protein":35.1,"carbs":32.5,"fats":16.9,"fiber":10.9}'::jsonb, 35.4, 475, 'https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=600&q=80', '🥘', 27),
(28, 'Soya Keema Bhurji with Crispy Fried Onions', 'Indian', 'broke', ARRAY['15-min','high-protein','fat-loss'], 15, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Place 55g soya chunks in a bowl, pour 300ml boiling water, and soak for 7 minutes until spongy.","timer_seconds":420,"tip":"⚠️ Where this goes wrong: Not squeezing the soaked soya chunks leaves a soggy, raw flavor. Press firmly in a clean cloth or fist until completely dry before chopping."},{"text":"Drain soya in a strainer, rinse with cold water, squeeze out all excess moisture firmly, and finely chop to coarse mince."},{"text":"Heat 10ml cooking oil in a pan on medium heat. Add 1 tsp minced ginger and 1 tsp minced garlic; sauté 30 seconds.","timer_seconds":30},{"text":"Add 1 finely chopped onion; cook for 3 minutes until light golden brown.","timer_seconds":180},{"text":"Add 1 chopped tomato, 1/2 tsp red chilli powder, 1/2 tsp garam masala, and 1/2 tsp salt; cook 2 minutes until saucy.","timer_seconds":120},{"text":"Toss in the minced soya with 3 tbsp water. Cover and simmer on low heat for 4 minutes so soya absorbs the spices.","timer_seconds":240},{"text":"Scatter 2 tbsp crispy golden fried onions over the warm plate for caramelized sweetness.","timer_seconds":60}]'::jsonb, '{"kcal":403,"protein":31.5,"carbs":34.8,"fats":16.4,"fiber":11.4}'::jsonb, 26.2, 365, 'https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=600&q=80', '🥘', 28),
(29, 'Masala Oats with Boiled Egg', 'Indian', 'broke', ARRAY['15-min','fat-loss'], 13, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Finely dice 1/2 small onion (40g), 1/2 small tomato (40g), and 1/2 green chilli.","tip":"⚠️ Where this goes wrong: Walking away while oats cook on high heat. Rolled oats stick and burn at the bottom of the pan rapidly; stir frequently over medium-low heat."},{"text":"Heat 8ml cooking oil in a small pan or electric kettle on medium heat for 30 seconds.","timer_seconds":30},{"text":"Add diced onion and green chilli; sauté for 90 seconds until translucent.","timer_seconds":90},{"text":"Add diced tomato, 1/4 tsp turmeric, 1/4 tsp garam masala, and 1/3 tsp salt; cook 1 minute until soft.","timer_seconds":60},{"text":"Add 50g rolled oats and pour in 250ml water; stir well to combine.","timer_seconds":30},{"text":"Simmer on low heat for 3 minutes, stirring continuously until oats turn into a thick savory porridge.","timer_seconds":180},{"text":"Turn off heat and let rest covered for 1 minute to finish swelling.","timer_seconds":60},{"text":"Boil 1 egg in your kettle for 7 minutes, peel, slice in half, and place on the oats with black pepper.","timer_seconds":420}]'::jsonb, '{"kcal":377,"protein":16.1,"carbs":41.4,"fats":17.1,"fiber":7.4}'::jsonb, 24.4, 423, 'https://images.unsplash.com/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=600&q=80', '🥣', 29),
