(34, 'Masala Oats with Spoon of Ghee', 'Indian', 'broke', ARRAY['15-min'], 10, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Finely dice 1/2 small onion (40g), 1/2 small tomato (40g), and 1/2 green chilli.","tip":"⚠️ Where this goes wrong: Walking away while oats cook on high heat. Rolled oats stick and burn at the bottom of the pan rapidly; stir frequently over medium-low heat."},{"text":"Heat 8ml cooking oil in a small pan or electric kettle on medium heat for 30 seconds.","timer_seconds":30},{"text":"Add diced onion and green chilli; sauté for 90 seconds until translucent.","timer_seconds":90},{"text":"Add diced tomato, 1/4 tsp turmeric, 1/4 tsp garam masala, and 1/3 tsp salt; cook 1 minute until soft.","timer_seconds":60},{"text":"Add 50g rolled oats and pour in 250ml water; stir well to combine.","timer_seconds":30},{"text":"Simmer on low heat for 3 minutes, stirring continuously until oats turn into a thick savory porridge.","timer_seconds":180},{"text":"Turn off heat and let rest covered for 1 minute to finish swelling.","timer_seconds":60},{"text":"Swirl 1 tsp warm desi ghee over the hot oats right at the table for rich homestyle warmth."}]'::jsonb, '{"kcal":359,"protein":9.8,"carbs":41,"fats":18.1,"fiber":7.4}'::jsonb, 20.4, 526, 'https://images.unsplash.com/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=600&q=80', '🥣', 34),
(35, 'Masala Oats with Sautéed Mushrooms', 'Indian', 'broke', ARRAY['15-min'], 10, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Finely dice 1/2 small onion (40g), 1/2 small tomato (40g), and 1/2 green chilli.","tip":"⚠️ Where this goes wrong: Walking away while oats cook on high heat. Rolled oats stick and burn at the bottom of the pan rapidly; stir frequently over medium-low heat."},{"text":"Heat 8ml cooking oil in a small pan or electric kettle on medium heat for 30 seconds.","timer_seconds":30},{"text":"Add diced onion and green chilli; sauté for 90 seconds until translucent.","timer_seconds":90},{"text":"Add diced tomato, 1/4 tsp turmeric, 1/4 tsp garam masala, and 1/3 tsp salt; cook 1 minute until soft.","timer_seconds":60},{"text":"Add 50g rolled oats and pour in 250ml water; stir well to combine.","timer_seconds":30},{"text":"Simmer on low heat for 3 minutes, stirring continuously until oats turn into a thick savory porridge.","timer_seconds":180},{"text":"Turn off heat and let rest covered for 1 minute to finish swelling.","timer_seconds":60},{"text":"Slice 50g button mushrooms and sauté in 1 tsp oil for 2 minutes before spooning on the oats.","timer_seconds":120}]'::jsonb, '{"kcal":316,"protein":11.3,"carbs":42.7,"fats":12.2,"fiber":7.9}'::jsonb, 32, 436, 'https://images.unsplash.com/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=600&q=80', '🥣', 35),
(36, 'Homestyle Curry with Paneer & Peas', 'Indian', 'broke', ARRAY['muscle-gain'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Finely chop 1 medium onion (80g), 2 small tomatoes (90g), and mince 2 cloves garlic and 1 slice ginger.","tip":"⚠️ Where this goes wrong: Rushing the bhunai (sautéing of onions and tomatoes). If the paste does not cook until oil separates, the gravy will taste raw and unpleasantly tart."},{"text":"Heat 12ml cooking oil in a pan on medium induction heat (800W) for 45 seconds.","timer_seconds":45},{"text":"Add minced ginger and garlic; cook for 30 seconds until fragrant.","timer_seconds":30},{"text":"Add chopped onions and sauté for 3.5 minutes until deep golden brown.","timer_seconds":210},{"text":"Add chopped tomatoes, 1/2 tsp turmeric, 1/2 tsp red chilli, 1/2 tsp garam masala, and 3/4 tsp salt. Cook for 3 minutes until oil glazes the edges.","timer_seconds":180},{"text":"Pour in 180ml hot water, stir well, bring to a gentle boil, and simmer on low for 4 minutes to create a rich gravy.","timer_seconds":240},{"text":"Slide 90g paneer cubes and 30g green peas into the simmering gravy for 3 minutes to turn luscious.","timer_seconds":180}]'::jsonb, '{"kcal":484,"protein":20.5,"carbs":26.9,"fats":33.6,"fiber":5.9}'::jsonb, 58.4, 488, 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?auto=format&fit=crop&w=600&q=80', '🥘', 36),
(37, 'Homestyle Curry with Tender Chicken Breast', 'Indian', 'broke', ARRAY['high-protein','fat-loss'], 22, ARRAY['1-pan','induction'], 1, '[{"text":"Finely chop 1 medium onion (80g), 2 small tomatoes (90g), and mince 2 cloves garlic and 1 slice ginger.","tip":"⚠️ Where this goes wrong: Rushing the bhunai (sautéing of onions and tomatoes). If the paste does not cook until oil separates, the gravy will taste raw and unpleasantly tart."},{"text":"Heat 12ml cooking oil in a pan on medium induction heat (800W) for 45 seconds.","timer_seconds":45},{"text":"Add minced ginger and garlic; cook for 30 seconds until fragrant.","timer_seconds":30},{"text":"Add chopped onions and sauté for 3.5 minutes until deep golden brown.","timer_seconds":210},{"text":"Add chopped tomatoes, 1/2 tsp turmeric, 1/2 tsp red chilli, 1/2 tsp garam masala, and 3/4 tsp salt. Cook for 3 minutes until oil glazes the edges.","timer_seconds":180},{"text":"Pour in 180ml hot water, stir well, bring to a gentle boil, and simmer on low for 4 minutes to create a rich gravy.","timer_seconds":240},{"text":"Dice 130g chicken breast into cubes; sear in the onion masala for 5 minutes until tender and cooked through.","timer_seconds":300}]'::jsonb, '{"kcal":411,"protein":43.6,"carbs":18.5,"fats":18.1,"fiber":5.1}'::jsonb, 59.6, 533, 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?auto=format&fit=crop&w=600&q=80', '🥘', 37),
