(39, 'Homestyle Curry with Soya Chunks & Potato', 'Indian', 'broke', ARRAY['high-protein','fat-loss'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Finely chop 1 medium onion (80g), 2 small tomatoes (90g), and mince 2 cloves garlic and 1 slice ginger.","tip":"⚠️ Where this goes wrong: Rushing the bhunai (sautéing of onions and tomatoes). If the paste does not cook until oil separates, the gravy will taste raw and unpleasantly tart."},{"text":"Heat 12ml cooking oil in a pan on medium induction heat (800W) for 45 seconds.","timer_seconds":45},{"text":"Add minced ginger and garlic; cook for 30 seconds until fragrant.","timer_seconds":30},{"text":"Add chopped onions and sauté for 3.5 minutes until deep golden brown.","timer_seconds":210},{"text":"Add chopped tomatoes, 1/2 tsp turmeric, 1/2 tsp red chilli, 1/2 tsp garam masala, and 3/4 tsp salt. Cook for 3 minutes until oil glazes the edges.","timer_seconds":180},{"text":"Pour in 180ml hot water, stir well, bring to a gentle boil, and simmer on low for 4 minutes to create a rich gravy.","timer_seconds":240},{"text":"Simmer 40g soaked soya chunks and 1 diced potato in the gravy for 4 minutes on low heat.","timer_seconds":240}]'::jsonb, '{"kcal":381,"protein":25.3,"carbs":42.2,"fats":13.7,"fiber":11.6}'::jsonb, 26.3, 440, 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?auto=format&fit=crop&w=600&q=80', '🥘', 39),
(40, 'Homestyle Curry with Button Mushrooms', 'Indian', 'broke', ARRAY['high-protein'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Finely chop 1 medium onion (80g), 2 small tomatoes (90g), and mince 2 cloves garlic and 1 slice ginger.","tip":"⚠️ Where this goes wrong: Rushing the bhunai (sautéing of onions and tomatoes). If the paste does not cook until oil separates, the gravy will taste raw and unpleasantly tart."},{"text":"Heat 12ml cooking oil in a pan on medium induction heat (800W) for 45 seconds.","timer_seconds":45},{"text":"Add minced ginger and garlic; cook for 30 seconds until fragrant.","timer_seconds":30},{"text":"Add chopped onions and sauté for 3.5 minutes until deep golden brown.","timer_seconds":210},{"text":"Add chopped tomatoes, 1/2 tsp turmeric, 1/2 tsp red chilli, 1/2 tsp garam masala, and 3/4 tsp salt. Cook for 3 minutes until oil glazes the edges.","timer_seconds":180},{"text":"Pour in 180ml hot water, stir well, bring to a gentle boil, and simmer on low for 4 minutes to create a rich gravy.","timer_seconds":240},{"text":"Halve 80g button mushrooms and simmer in the curry for 3.5 minutes until juicy and flavorful.","timer_seconds":210}]'::jsonb, '{"kcal":214,"protein":5.8,"carbs":21.1,"fats":13.7,"fiber":5.9}'::jsonb, 41.4, 428, 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?auto=format&fit=crop&w=600&q=80', '🥘', 40),
(41, 'Homestyle Curry with Steamed Basmati Rice', 'Indian', 'broke', ARRAY['high-protein'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Finely chop 1 medium onion (80g), 2 small tomatoes (90g), and mince 2 cloves garlic and 1 slice ginger.","tip":"⚠️ Where this goes wrong: Rushing the bhunai (sautéing of onions and tomatoes). If the paste does not cook until oil separates, the gravy will taste raw and unpleasantly tart."},{"text":"Heat 12ml cooking oil in a pan on medium induction heat (800W) for 45 seconds.","timer_seconds":45},{"text":"Add minced ginger and garlic; cook for 30 seconds until fragrant.","timer_seconds":30},{"text":"Add chopped onions and sauté for 3.5 minutes until deep golden brown.","timer_seconds":210},{"text":"Add chopped tomatoes, 1/2 tsp turmeric, 1/2 tsp red chilli, 1/2 tsp garam masala, and 3/4 tsp salt. Cook for 3 minutes until oil glazes the edges.","timer_seconds":180},{"text":"Pour in 180ml hot water, stir well, bring to a gentle boil, and simmer on low for 4 minutes to create a rich gravy.","timer_seconds":240},{"text":"Serve curry over a bowl of 120g warm, fluffy steamed basmati rice with fresh coriander.","timer_seconds":60}]'::jsonb, '{"kcal":449,"protein":8.2,"carbs":74.5,"fats":13.9,"fiber":6}'::jsonb, 19.9, 428, 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?auto=format&fit=crop&w=600&q=80', '🥘', 41),
(42, 'Homestyle Curry with Desi Ghee & Kasuri Methi', 'Indian', 'broke', ARRAY['high-protein'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Finely chop 1 medium onion (80g), 2 small tomatoes (90g), and mince 2 cloves garlic and 1 slice ginger.","tip":"⚠️ Where this goes wrong: Rushing the bhunai (sautéing of onions and tomatoes). If the paste does not cook until oil separates, the gravy will taste raw and unpleasantly tart."},{"text":"Heat 12ml cooking oil in a pan on medium induction heat (800W) for 45 seconds.","timer_seconds":45},{"text":"Add minced ginger and garlic; cook for 30 seconds until fragrant.","timer_seconds":30},{"text":"Add chopped onions and sauté for 3.5 minutes until deep golden brown.","timer_seconds":210},{"text":"Add chopped tomatoes, 1/2 tsp turmeric, 1/2 tsp red chilli, 1/2 tsp garam masala, and 3/4 tsp salt. Cook for 3 minutes until oil glazes the edges.","timer_seconds":180},{"text":"Pour in 180ml hot water, stir well, bring to a gentle boil, and simmer on low for 4 minutes to create a rich gravy.","timer_seconds":240},{"text":"Swirl 10ml desi ghee over the finished curry and garnish with crushed dry fenugreek or coriander.","timer_seconds":30}]'::jsonb, '{"kcal":287,"protein":3.3,"carbs":18.5,"fats":23.4,"fiber":5.1}'::jsonb, 23.1, 518, 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?auto=format&fit=crop&w=600&q=80', '🥘', 42),
(43, 'Paneer Tikka Bowl with Seasoned Quinoa', 'Indian', 'balanced', ARRAY['high-protein','muscle-gain'], 22, ARRAY['1-pan','induction'], 1, '[{"text":"Cut 110g paneer into bite-sized 2cm cubes, cut 1/2 onion and 1/2 capsicum into square petals.","tip":"⚠️ Where this goes wrong: Sautéing paneer over low heat for too long squeezes out moisture and turns it leathery. Sear on high heat for charred spots while keeping the core soft."},{"text":"In a bowl, mix 45g thick curd, 1/2 tsp red chilli, 1/2 tsp turmeric, 1/2 tsp garam masala, and 1/2 tsp salt.","timer_seconds":45},{"text":"Toss paneer, onion petals, and capsicum in the spiced yogurt marinade; let sit for 6 minutes.","timer_seconds":360},{"text":"Heat 10ml oil in a wide frying pan on medium-high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add the marinated paneer and veggies in a single layer. Sear untouched for 2 minutes until deeply charred underneath.","timer_seconds":120},{"text":"Flip gently and sear the other side for 1.5 minutes; remove to a serving bowl and squeeze 1/2 lemon.","timer_seconds":90},{"text":"Boil 50g quinoa in 100ml salted water for 12 minutes, fluff, and use as high-protein bowl base.","timer_seconds":720}]'::jsonb, '{"kcal":675,"protein":30.4,"carbs":49.6,"fats":39.8,"fiber":7.7}'::jsonb, 83.1, 642, 'https://images.unsplash.com/photo-1631515243349-e0cb75fb8d3a?auto=format&fit=crop&w=600&q=80', '🥗', 43),
