(45, 'Paneer Tikka Bowl with Mint Curd Raita', 'Indian', 'balanced', ARRAY['high-protein','muscle-gain'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Cut 110g paneer into bite-sized 2cm cubes, cut 1/2 onion and 1/2 capsicum into square petals.","tip":"⚠️ Where this goes wrong: Sautéing paneer over low heat for too long squeezes out moisture and turns it leathery. Sear on high heat for charred spots while keeping the core soft."},{"text":"In a bowl, mix 45g thick curd, 1/2 tsp red chilli, 1/2 tsp turmeric, 1/2 tsp garam masala, and 1/2 tsp salt.","timer_seconds":45},{"text":"Toss paneer, onion petals, and capsicum in the spiced yogurt marinade; let sit for 6 minutes.","timer_seconds":360},{"text":"Heat 10ml oil in a wide frying pan on medium-high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add the marinated paneer and veggies in a single layer. Sear untouched for 2 minutes until deeply charred underneath.","timer_seconds":120},{"text":"Flip gently and sear the other side for 1.5 minutes; remove to a serving bowl and squeeze 1/2 lemon.","timer_seconds":90},{"text":"Whisk 60g cold dahi with a pinch of cumin and chopped coriander to drizzle as a cooling sauce.","timer_seconds":45}]'::jsonb, '{"kcal":529,"protein":25.5,"carbs":20.5,"fats":38.6,"fiber":4.3}'::jsonb, 68.9, 462, 'https://images.unsplash.com/photo-1631515243349-e0cb75fb8d3a?auto=format&fit=crop&w=600&q=80', '🥗', 45),
(46, 'Paneer Tikka Bowl with Sliced Onion Laccha', 'Indian', 'balanced', ARRAY['high-protein','muscle-gain'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Cut 110g paneer into bite-sized 2cm cubes, cut 1/2 onion and 1/2 capsicum into square petals.","tip":"⚠️ Where this goes wrong: Sautéing paneer over low heat for too long squeezes out moisture and turns it leathery. Sear on high heat for charred spots while keeping the core soft."},{"text":"In a bowl, mix 45g thick curd, 1/2 tsp red chilli, 1/2 tsp turmeric, 1/2 tsp garam masala, and 1/2 tsp salt.","timer_seconds":45},{"text":"Toss paneer, onion petals, and capsicum in the spiced yogurt marinade; let sit for 6 minutes.","timer_seconds":360},{"text":"Heat 10ml oil in a wide frying pan on medium-high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add the marinated paneer and veggies in a single layer. Sear untouched for 2 minutes until deeply charred underneath.","timer_seconds":120},{"text":"Flip gently and sear the other side for 1.5 minutes; remove to a serving bowl and squeeze 1/2 lemon.","timer_seconds":90},{"text":"Slice 1/2 onion into fine rings, toss with lemon juice and a pinch of chilli, and pile on the side.","timer_seconds":60}]'::jsonb, '{"kcal":517,"protein":24.1,"carbs":23.9,"fats":36.9,"fiber":5.6}'::jsonb, 67.8, 447, 'https://images.unsplash.com/photo-1631515243349-e0cb75fb8d3a?auto=format&fit=crop&w=600&q=80', '🥗', 46),
(47, 'Paneer Tikka Bowl with Charred Capsicum & Corn', 'Indian', 'balanced', ARRAY['high-protein','muscle-gain'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Cut 110g paneer into bite-sized 2cm cubes, cut 1/2 onion and 1/2 capsicum into square petals.","tip":"⚠️ Where this goes wrong: Sautéing paneer over low heat for too long squeezes out moisture and turns it leathery. Sear on high heat for charred spots while keeping the core soft."},{"text":"In a bowl, mix 45g thick curd, 1/2 tsp red chilli, 1/2 tsp turmeric, 1/2 tsp garam masala, and 1/2 tsp salt.","timer_seconds":45},{"text":"Toss paneer, onion petals, and capsicum in the spiced yogurt marinade; let sit for 6 minutes.","timer_seconds":360},{"text":"Heat 10ml oil in a wide frying pan on medium-high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add the marinated paneer and veggies in a single layer. Sear untouched for 2 minutes until deeply charred underneath.","timer_seconds":120},{"text":"Flip gently and sear the other side for 1.5 minutes; remove to a serving bowl and squeeze 1/2 lemon.","timer_seconds":90},{"text":"Sear 40g sweet corn kernels alongside extra capsicum until blistered and sweet; toss in bowl.","timer_seconds":120}]'::jsonb, '{"kcal":526,"protein":24.6,"carbs":25.1,"fats":37.2,"fiber":5.2}'::jsonb, 70, 487, 'https://images.unsplash.com/photo-1631515243349-e0cb75fb8d3a?auto=format&fit=crop&w=600&q=80', '🥗', 47),
(48, 'Paneer Tikka Bowl with Toasted Pav', 'Indian', 'balanced', ARRAY['high-protein','muscle-gain'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Cut 110g paneer into bite-sized 2cm cubes, cut 1/2 onion and 1/2 capsicum into square petals.","tip":"⚠️ Where this goes wrong: Sautéing paneer over low heat for too long squeezes out moisture and turns it leathery. Sear on high heat for charred spots while keeping the core soft."},{"text":"In a bowl, mix 45g thick curd, 1/2 tsp red chilli, 1/2 tsp turmeric, 1/2 tsp garam masala, and 1/2 tsp salt.","timer_seconds":45},{"text":"Toss paneer, onion petals, and capsicum in the spiced yogurt marinade; let sit for 6 minutes.","timer_seconds":360},{"text":"Heat 10ml oil in a wide frying pan on medium-high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add the marinated paneer and veggies in a single layer. Sear untouched for 2 minutes until deeply charred underneath.","timer_seconds":120},{"text":"Flip gently and sear the other side for 1.5 minutes; remove to a serving bowl and squeeze 1/2 lemon.","timer_seconds":90},{"text":"Toast 2 buttered pav buns on the paneer pan to absorb all the spicy charred pan juices.","timer_seconds":60}]'::jsonb, '{"kcal":709,"protein":28.8,"carbs":47.5,"fats":45.2,"fiber":6}'::jsonb, 78.1, 543, 'https://images.unsplash.com/photo-1631515243349-e0cb75fb8d3a?auto=format&fit=crop&w=600&q=80', '🥗', 48),
(49, 'Paneer Tikka Bowl with Roasted Cumin Butter', 'Indian', 'balanced', ARRAY['muscle-gain'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Cut 110g paneer into bite-sized 2cm cubes, cut 1/2 onion and 1/2 capsicum into square petals.","tip":"⚠️ Where this goes wrong: Sautéing paneer over low heat for too long squeezes out moisture and turns it leathery. Sear on high heat for charred spots while keeping the core soft."},{"text":"In a bowl, mix 45g thick curd, 1/2 tsp red chilli, 1/2 tsp turmeric, 1/2 tsp garam masala, and 1/2 tsp salt.","timer_seconds":45},{"text":"Toss paneer, onion petals, and capsicum in the spiced yogurt marinade; let sit for 6 minutes.","timer_seconds":360},{"text":"Heat 10ml oil in a wide frying pan on medium-high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add the marinated paneer and veggies in a single layer. Sear untouched for 2 minutes until deeply charred underneath.","timer_seconds":120},{"text":"Flip gently and sear the other side for 1.5 minutes; remove to a serving bowl and squeeze 1/2 lemon.","timer_seconds":90},{"text":"Melt 10g butter with 1/2 tsp roasted cumin powder and brush over the hot paneer cubes.","timer_seconds":40}]'::jsonb, '{"kcal":571,"protein":23.8,"carbs":18.4,"fats":45.3,"fiber":4.4}'::jsonb, 70, 541, 'https://images.unsplash.com/photo-1631515243349-e0cb75fb8d3a?auto=format&fit=crop&w=600&q=80', '🥗', 49),
(50, 'Biryani Bowl with Crispy Fried Onions (Birista)', 'Indian', 'broke', ARRAY['muscle-gain'], 20, ARRAY['1-pan','induction'], 1, '[{"text":"Rinse 75g basmati rice twice; boil in 500ml salted water for 6.5 minutes until 80% cooked, then drain well.","timer_seconds":390,"tip":"⚠️ Where this goes wrong: High heat during dum cooking scorches the bottom layer. Always lower induction power to minimum (200W) and keep the lid sealed so steam gently infuses the rice."},{"text":"Thinly slice 1 medium onion (70g) and mince ginger and garlic."},{"text":"Melt 12ml desi ghee in a heavy pan on medium heat. Sauté sliced onions for 4 minutes until deeply caramelized.","timer_seconds":240},{"text":"Add ginger, garlic, 1 chopped tomato, 1/2 tsp turmeric, 1 tsp biryani masala, and 1/2 tsp salt; cook 2.5 minutes until oil surfaces.","timer_seconds":150},{"text":"Lower heat to minimum. Spread the drained basmati rice evenly over the masala layer; sprinkle 2 tbsp water.","timer_seconds":40},{"text":"Seal tightly with lid and steam on low (200W) for 6 minutes until rice grains are fluffy and elongated.","timer_seconds":360},{"text":"Gently fluff from the edges with a flat spatula and garnish with chopped coriander.","timer_seconds":30},{"text":"Fry 40g thinly sliced onion in 1 tbsp hot oil for 3 minutes until dark golden and crispy; scatter over rice.","timer_seconds":180}]'::jsonb, '{"kcal":553,"protein":8.2,"carbs":78.1,"fats":23.4,"fiber":5.2}'::jsonb, 27.3, 549, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=600&q=80', '🍛', 50)
INSERT INTO public.recipes (id, title, cuisine, budget_tier, goals, minutes, equipment_tags, servings, steps, macros, cost_per_serving, cost_full_pack, image_url, emoji, gradient_seed) VALUES
(51, 'Biryani Bowl with Spiced Boiled Egg', 'Indian', 'broke', ARRAY['muscle-gain'], 20, ARRAY['1-pan','induction'], 1, '[{"text":"Rinse 75g basmati rice twice; boil in 500ml salted water for 6.5 minutes until 80% cooked, then drain well.","timer_seconds":390,"tip":"⚠️ Where this goes wrong: High heat during dum cooking scorches the bottom layer. Always lower induction power to minimum (200W) and keep the lid sealed so steam gently infuses the rice."},{"text":"Thinly slice 1 medium onion (70g) and mince ginger and garlic."},{"text":"Melt 12ml desi ghee in a heavy pan on medium heat. Sauté sliced onions for 4 minutes until deeply caramelized.","timer_seconds":240},{"text":"Add ginger, garlic, 1 chopped tomato, 1/2 tsp turmeric, 1 tsp biryani masala, and 1/2 tsp salt; cook 2.5 minutes until oil surfaces.","timer_seconds":150},{"text":"Lower heat to minimum. Spread the drained basmati rice evenly over the masala layer; sprinkle 2 tbsp water.","timer_seconds":40},{"text":"Seal tightly with lid and steam on low (200W) for 6 minutes until rice grains are fluffy and elongated.","timer_seconds":360},{"text":"Gently fluff from the edges with a flat spatula and garnish with chopped coriander.","timer_seconds":30},{"text":"Boil 1 egg (7.5 mins), peel, toss in 1/2 tsp ghee with turmeric and chilli for 60s, and place in bowl.","timer_seconds":450}]'::jsonb, '{"kcal":526,"protein":14.3,"carbs":75.8,"fats":18.7,"fiber":5.2}'::jsonb, 33.8, 505, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=600&q=80', '🍛', 51),
(52, 'Biryani Bowl with Marinated Chicken Breast', 'Indian', 'balanced', ARRAY['high-protein','muscle-gain'], 23, ARRAY['1-pan','induction'], 1, '[{"text":"Rinse 75g basmati rice twice; boil in 500ml salted water for 6.5 minutes until 80% cooked, then drain well.","timer_seconds":390,"tip":"⚠️ Where this goes wrong: High heat during dum cooking scorches the bottom layer. Always lower induction power to minimum (200W) and keep the lid sealed so steam gently infuses the rice."},{"text":"Thinly slice 1 medium onion (70g) and mince ginger and garlic."},{"text":"Melt 12ml desi ghee in a heavy pan on medium heat. Sauté sliced onions for 4 minutes until deeply caramelized.","timer_seconds":240},{"text":"Add ginger, garlic, 1 chopped tomato, 1/2 tsp turmeric, 1 tsp biryani masala, and 1/2 tsp salt; cook 2.5 minutes until oil surfaces.","timer_seconds":150},{"text":"Lower heat to minimum. Spread the drained basmati rice evenly over the masala layer; sprinkle 2 tbsp water.","timer_seconds":40},{"text":"Seal tightly with lid and steam on low (200W) for 6 minutes until rice grains are fluffy and elongated.","timer_seconds":360},{"text":"Gently fluff from the edges with a flat spatula and garnish with chopped coriander.","timer_seconds":30},{"text":"Marinate 120g diced chicken in spices, sear in the base masala for 4 minutes before layering rice.","timer_seconds":240}]'::jsonb, '{"kcal":647,"protein":44.9,"carbs":74.4,"fats":17.7,"fiber":4.5}'::jsonb, 65.3, 589, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=600&q=80', '🍛', 52),
(53, 'Biryani Bowl with Golden Paneer Cubes', 'Indian', 'broke', ARRAY['muscle-gain'], 20, ARRAY['1-pan','induction'], 1, '[{"text":"Rinse 75g basmati rice twice; boil in 500ml salted water for 6.5 minutes until 80% cooked, then drain well.","timer_seconds":390,"tip":"⚠️ Where this goes wrong: High heat during dum cooking scorches the bottom layer. Always lower induction power to minimum (200W) and keep the lid sealed so steam gently infuses the rice."},{"text":"Thinly slice 1 medium onion (70g) and mince ginger and garlic."},{"text":"Melt 12ml desi ghee in a heavy pan on medium heat. Sauté sliced onions for 4 minutes until deeply caramelized.","timer_seconds":240},{"text":"Add ginger, garlic, 1 chopped tomato, 1/2 tsp turmeric, 1 tsp biryani masala, and 1/2 tsp salt; cook 2.5 minutes until oil surfaces.","timer_seconds":150},{"text":"Lower heat to minimum. Spread the drained basmati rice evenly over the masala layer; sprinkle 2 tbsp water.","timer_seconds":40},{"text":"Seal tightly with lid and steam on low (200W) for 6 minutes until rice grains are fluffy and elongated.","timer_seconds":360},{"text":"Gently fluff from the edges with a flat spatula and garnish with chopped coriander.","timer_seconds":30},{"text":"Pan-sear 70g paneer cubes in ghee for 2 minutes until golden, then fold into the steaming biryani.","timer_seconds":120}]'::jsonb, '{"kcal":652,"protein":20.3,"carbs":76.5,"fats":28.8,"fiber":4.5}'::jsonb, 54.2, 504, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=600&q=80', '🍛', 53),
(54, 'Biryani Bowl with Chilled Dahi Raita', 'Indian', 'broke', ARRAY['muscle-gain'], 20, ARRAY['1-pan','induction'], 1, '[{"text":"Rinse 75g basmati rice twice; boil in 500ml salted water for 6.5 minutes until 80% cooked, then drain well.","timer_seconds":390,"tip":"⚠️ Where this goes wrong: High heat during dum cooking scorches the bottom layer. Always lower induction power to minimum (200W) and keep the lid sealed so steam gently infuses the rice."},{"text":"Thinly slice 1 medium onion (70g) and mince ginger and garlic."},{"text":"Melt 12ml desi ghee in a heavy pan on medium heat. Sauté sliced onions for 4 minutes until deeply caramelized.","timer_seconds":240},{"text":"Add ginger, garlic, 1 chopped tomato, 1/2 tsp turmeric, 1 tsp biryani masala, and 1/2 tsp salt; cook 2.5 minutes until oil surfaces.","timer_seconds":150},{"text":"Lower heat to minimum. Spread the drained basmati rice evenly over the masala layer; sprinkle 2 tbsp water.","timer_seconds":40},{"text":"Seal tightly with lid and steam on low (200W) for 6 minutes until rice grains are fluffy and elongated.","timer_seconds":360},{"text":"Gently fluff from the edges with a flat spatula and garnish with chopped coriander.","timer_seconds":30},{"text":"Whisk 70g thick dahi with a pinch of roasted cumin and salt; serve in a bowl alongside the hot biryani.","timer_seconds":45}]'::jsonb, '{"kcal":498,"protein":10.6,"carbs":78.5,"fats":15.9,"fiber":4.7}'::jsonb, 31.4, 492, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=600&q=80', '🍛', 54),
(55, 'Biryani Bowl with Soya Keema', 'Indian', 'broke', ARRAY['high-protein','muscle-gain'], 20, ARRAY['1-pan','induction'], 1, '[{"text":"Rinse 75g basmati rice twice; boil in 500ml salted water for 6.5 minutes until 80% cooked, then drain well.","timer_seconds":390,"tip":"⚠️ Where this goes wrong: High heat during dum cooking scorches the bottom layer. Always lower induction power to minimum (200W) and keep the lid sealed so steam gently infuses the rice."},{"text":"Thinly slice 1 medium onion (70g) and mince ginger and garlic."},{"text":"Melt 12ml desi ghee in a heavy pan on medium heat. Sauté sliced onions for 4 minutes until deeply caramelized.","timer_seconds":240},{"text":"Add ginger, garlic, 1 chopped tomato, 1/2 tsp turmeric, 1 tsp biryani masala, and 1/2 tsp salt; cook 2.5 minutes until oil surfaces.","timer_seconds":150},{"text":"Lower heat to minimum. Spread the drained basmati rice evenly over the masala layer; sprinkle 2 tbsp water.","timer_seconds":40},{"text":"Seal tightly with lid and steam on low (200W) for 6 minutes until rice grains are fluffy and elongated.","timer_seconds":360},{"text":"Gently fluff from the edges with a flat spatula and garnish with chopped coriander.","timer_seconds":30},{"text":"Soak 35g soya chunks, squeeze dry, mince, and cook in the masala base before layering rice.","timer_seconds":240}]'::jsonb, '{"kcal":569,"protein":25.9,"carbs":85.9,"fats":13.6,"fiber":9}'::jsonb, 32.4, 464, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=600&q=80', '🍛', 55),
(56, 'Biryani Bowl with Roasted Cashews & Ghee', 'Indian', 'broke', ARRAY['muscle-gain'], 20, ARRAY['1-pan','induction'], 1, '[{"text":"Rinse 75g basmati rice twice; boil in 500ml salted water for 6.5 minutes until 80% cooked, then drain well.","timer_seconds":390,"tip":"⚠️ Where this goes wrong: High heat during dum cooking scorches the bottom layer. Always lower induction power to minimum (200W) and keep the lid sealed so steam gently infuses the rice."},{"text":"Thinly slice 1 medium onion (70g) and mince ginger and garlic."},{"text":"Melt 12ml desi ghee in a heavy pan on medium heat. Sauté sliced onions for 4 minutes until deeply caramelized.","timer_seconds":240},{"text":"Add ginger, garlic, 1 chopped tomato, 1/2 tsp turmeric, 1 tsp biryani masala, and 1/2 tsp salt; cook 2.5 minutes until oil surfaces.","timer_seconds":150},{"text":"Lower heat to minimum. Spread the drained basmati rice evenly over the masala layer; sprinkle 2 tbsp water.","timer_seconds":40},{"text":"Seal tightly with lid and steam on low (200W) for 6 minutes until rice grains are fluffy and elongated.","timer_seconds":360},{"text":"Gently fluff from the edges with a flat spatula and garnish with chopped coriander.","timer_seconds":30},{"text":"Fry 20g peanuts or cashews in 1 tsp desi ghee until fragrant and golden; scatter over top.","timer_seconds":90}]'::jsonb, '{"kcal":616,"protein":12.9,"carbs":77.6,"fats":29.2,"fiber":6.2}'::jsonb, 33.1, 459, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=600&q=80', '🍛', 56),
(57, 'Pasta Aglio e Olio with Sautéed Button Mushrooms', 'Italian', 'broke', ARRAY['15-min','muscle-gain'], 12, ARRAY['1-pan','induction'], 1, '[{"text":"Bring 1 liter water to a rolling boil with 1 tsp salt in a pot or pan.","timer_seconds":240,"tip":"⚠️ Where this goes wrong: Burning the garlic. Minced or sliced garlic burns within seconds if heat is high, leaving a bitter taste. Sauté very gently on low heat until pale blonde."},{"text":"Drop 85g fettuccine pasta into boiling water; cook for 8 minutes until al dente.","timer_seconds":480},{"text":"Scoop out and reserve 60ml (1/4 cup) starchy pasta water, then drain pasta.","timer_seconds":30},{"text":"In the same pan, heat 20ml oil on lowest heat (200W). Add 4 thinly sliced cloves of garlic and chilli flakes.","timer_seconds":45},{"text":"Gently sizzle garlic for 2 minutes until light blonde — do not let it turn brown.","timer_seconds":120},{"text":"Toss in drained pasta and 3 tbsp reserved pasta water; toss vigorously for 1 minute until a glossy emulsified sauce forms.","timer_seconds":60},{"text":"Stir in chopped fresh coriander or parsley and season with a pinch of salt.","timer_seconds":20},{"text":"Slice 70g button mushrooms, sauté in 1 tsp oil for 2.5 minutes until browned and juicy, and fold into pasta.","timer_seconds":150}]'::jsonb, '{"kcal":519,"protein":14.4,"carbs":67.9,"fats":21.9,"fiber":4.6}'::jsonb, 49.5, 389, 'https://images.unsplash.com/photo-1546549032-9571cd6b27df?auto=format&fit=crop&w=600&q=80', '🍝', 57),
(58, 'Pasta Aglio e Olio with Grated Cheese Slice', 'Italian', 'broke', ARRAY['15-min','muscle-gain'], 12, ARRAY['1-pan','induction'], 1, '[{"text":"Bring 1 liter water to a rolling boil with 1 tsp salt in a pot or pan.","timer_seconds":240,"tip":"⚠️ Where this goes wrong: Burning the garlic. Minced or sliced garlic burns within seconds if heat is high, leaving a bitter taste. Sauté very gently on low heat until pale blonde."},{"text":"Drop 85g fettuccine pasta into boiling water; cook for 8 minutes until al dente.","timer_seconds":480},{"text":"Scoop out and reserve 60ml (1/4 cup) starchy pasta water, then drain pasta.","timer_seconds":30},{"text":"In the same pan, heat 20ml oil on lowest heat (200W). Add 4 thinly sliced cloves of garlic and chilli flakes.","timer_seconds":45},{"text":"Gently sizzle garlic for 2 minutes until light blonde — do not let it turn brown.","timer_seconds":120},{"text":"Toss in drained pasta and 3 tbsp reserved pasta water; toss vigorously for 1 minute until a glossy emulsified sauce forms.","timer_seconds":60},{"text":"Stir in chopped fresh coriander or parsley and season with a pinch of salt.","timer_seconds":20},{"text":"Tear 1 cheese slice into ribbons and toss with steaming pasta off the heat until melted and velvety.","timer_seconds":30}]'::jsonb, '{"kcal":569,"protein":16.2,"carbs":66.1,"fats":27.2,"fiber":3.9}'::jsonb, 37.8, 434, 'https://images.unsplash.com/photo-1546549032-9571cd6b27df?auto=format&fit=crop&w=600&q=80', '🍝', 58),
