(62, 'Pasta Aglio e Olio with Sweet Corn & Chilli', 'Italian', 'broke', ARRAY['15-min','muscle-gain'], 12, ARRAY['1-pan','induction'], 1, '[{"text":"Bring 1 liter water to a rolling boil with 1 tsp salt in a pot or pan.","timer_seconds":240,"tip":"⚠️ Where this goes wrong: Burning the garlic. Minced or sliced garlic burns within seconds if heat is high, leaving a bitter taste. Sauté very gently on low heat until pale blonde."},{"text":"Drop 85g fettuccine pasta into boiling water; cook for 8 minutes until al dente.","timer_seconds":480},{"text":"Scoop out and reserve 60ml (1/4 cup) starchy pasta water, then drain pasta.","timer_seconds":30},{"text":"In the same pan, heat 20ml oil on lowest heat (200W). Add 4 thinly sliced cloves of garlic and chilli flakes.","timer_seconds":45},{"text":"Gently sizzle garlic for 2 minutes until light blonde — do not let it turn brown.","timer_seconds":120},{"text":"Toss in drained pasta and 3 tbsp reserved pasta water; toss vigorously for 1 minute until a glossy emulsified sauce forms.","timer_seconds":60},{"text":"Stir in chopped fresh coriander or parsley and season with a pinch of salt.","timer_seconds":20},{"text":"Toss 40g sweet corn kernels into the garlic oil for 1 minute before tossing with pasta.","timer_seconds":60}]'::jsonb, '{"kcal":538,"protein":13.5,"carbs":73.2,"fats":22.1,"fiber":5}'::jsonb, 33.2, 364, 'https://images.unsplash.com/photo-1546549032-9571cd6b27df?auto=format&fit=crop&w=600&q=80', '🍝', 62),
(63, 'Pasta Aglio e Olio with Butter Glaze', 'Italian', 'broke', ARRAY['15-min','muscle-gain'], 12, ARRAY['1-pan','induction'], 1, '[{"text":"Bring 1 liter water to a rolling boil with 1 tsp salt in a pot or pan.","timer_seconds":240,"tip":"⚠️ Where this goes wrong: Burning the garlic. Minced or sliced garlic burns within seconds if heat is high, leaving a bitter taste. Sauté very gently on low heat until pale blonde."},{"text":"Drop 85g fettuccine pasta into boiling water; cook for 8 minutes until al dente.","timer_seconds":480},{"text":"Scoop out and reserve 60ml (1/4 cup) starchy pasta water, then drain pasta.","timer_seconds":30},{"text":"In the same pan, heat 20ml oil on lowest heat (200W). Add 4 thinly sliced cloves of garlic and chilli flakes.","timer_seconds":45},{"text":"Gently sizzle garlic for 2 minutes until light blonde — do not let it turn brown.","timer_seconds":120},{"text":"Toss in drained pasta and 3 tbsp reserved pasta water; toss vigorously for 1 minute until a glossy emulsified sauce forms.","timer_seconds":60},{"text":"Stir in chopped fresh coriander or parsley and season with a pinch of salt.","timer_seconds":20},{"text":"Melt 12g cold salted butter during the final toss for a rich restaurant-style pasta glaze.","timer_seconds":30}]'::jsonb, '{"kcal":590,"protein":12.4,"carbs":65.6,"fats":31.4,"fiber":3.9}'::jsonb, 33.5, 380, 'https://images.unsplash.com/photo-1546549032-9571cd6b27df?auto=format&fit=crop&w=600&q=80', '🍝', 63),
(64, 'Tomato Basil Penne with Melting Mozzarella & Cheddar', 'Italian', 'broke', ARRAY['15-min','muscle-gain'], 15, ARRAY['1-pan','induction'], 1, '[{"text":"Boil 85g pasta in 1 liter salted boiling water for 8 minutes until al dente; reserve 60ml pasta water and drain.","timer_seconds":480,"tip":"⚠️ Where this goes wrong: Under-cooking tomatoes produces a watery, acidic sauce. Sauté tomatoes until broken down into a jammy consistency, then loosen with starchy pasta water."},{"text":"Finely chop 2 ripe tomatoes (120g), 1/2 small onion (35g), and mince 2 cloves garlic."},{"text":"Heat 12ml cooking oil in a pan on medium heat. Sauté garlic and onions for 2 minutes until soft.","timer_seconds":120},{"text":"Add chopped tomatoes, 1/2 tsp salt, and a pinch of sugar; cook for 4 minutes, crushing tomatoes until a rich sauce forms.","timer_seconds":240},{"text":"Pour in 3 tbsp reserved pasta water and simmer for 1 minute until glossy.","timer_seconds":60},{"text":"Toss drained pasta into the sauce for 90 seconds until thoroughly coated.","timer_seconds":90},{"text":"Tear 1 cheese slice into ribbons, fold into pasta, and cover for 45 seconds until stringy and melted.","timer_seconds":45}]'::jsonb, '{"kcal":520,"protein":17,"carbs":71.4,"fats":19.1,"fiber":4.9}'::jsonb, 43, 451, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=600&q=80', '🍝', 64),
(65, 'Tomato Basil Penne with Sautéed Mushrooms', 'Italian', 'broke', ARRAY['15-min','muscle-gain'], 15, ARRAY['1-pan','induction'], 1, '[{"text":"Boil 85g pasta in 1 liter salted boiling water for 8 minutes until al dente; reserve 60ml pasta water and drain.","timer_seconds":480,"tip":"⚠️ Where this goes wrong: Under-cooking tomatoes produces a watery, acidic sauce. Sauté tomatoes until broken down into a jammy consistency, then loosen with starchy pasta water."},{"text":"Finely chop 2 ripe tomatoes (120g), 1/2 small onion (35g), and mince 2 cloves garlic."},{"text":"Heat 12ml cooking oil in a pan on medium heat. Sauté garlic and onions for 2 minutes until soft.","timer_seconds":120},{"text":"Add chopped tomatoes, 1/2 tsp salt, and a pinch of sugar; cook for 4 minutes, crushing tomatoes until a rich sauce forms.","timer_seconds":240},{"text":"Pour in 3 tbsp reserved pasta water and simmer for 1 minute until glossy.","timer_seconds":60},{"text":"Toss drained pasta into the sauce for 90 seconds until thoroughly coated.","timer_seconds":90},{"text":"Sear 70g sliced button mushrooms in 1 tsp butter for 3 minutes, then toss into the red sauce.","timer_seconds":180}]'::jsonb, '{"kcal":514,"protein":15.3,"carbs":73.2,"fats":18.7,"fiber":5.6}'::jsonb, 58.1, 462, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=600&q=80', '🍝', 65),
(66, 'Tomato Basil Penne with Herbed Chicken Breast', 'Italian', 'balanced', ARRAY['high-protein','muscle-gain'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Boil 85g pasta in 1 liter salted boiling water for 8 minutes until al dente; reserve 60ml pasta water and drain.","timer_seconds":480,"tip":"⚠️ Where this goes wrong: Under-cooking tomatoes produces a watery, acidic sauce. Sauté tomatoes until broken down into a jammy consistency, then loosen with starchy pasta water."},{"text":"Finely chop 2 ripe tomatoes (120g), 1/2 small onion (35g), and mince 2 cloves garlic."},{"text":"Heat 12ml cooking oil in a pan on medium heat. Sauté garlic and onions for 2 minutes until soft.","timer_seconds":120},{"text":"Add chopped tomatoes, 1/2 tsp salt, and a pinch of sugar; cook for 4 minutes, crushing tomatoes until a rich sauce forms.","timer_seconds":240},{"text":"Pour in 3 tbsp reserved pasta water and simmer for 1 minute until glossy.","timer_seconds":60},{"text":"Toss drained pasta into the sauce for 90 seconds until thoroughly coated.","timer_seconds":90},{"text":"Pan-sear 110g seasoned chicken breast chunks for 4 minutes, then fold into the pasta sauce.","timer_seconds":240}]'::jsonb, '{"kcal":637,"protein":47.1,"carbs":70.9,"fats":17.6,"fiber":4.9}'::jsonb, 69.4, 511, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=600&q=80', '🍝', 66),
