(69, 'Tomato Basil Penne with Baby Spinach Toss', 'Italian', 'broke', ARRAY['15-min'], 15, ARRAY['1-pan','induction'], 1, '[{"text":"Boil 85g pasta in 1 liter salted boiling water for 8 minutes until al dente; reserve 60ml pasta water and drain.","timer_seconds":480,"tip":"⚠️ Where this goes wrong: Under-cooking tomatoes produces a watery, acidic sauce. Sauté tomatoes until broken down into a jammy consistency, then loosen with starchy pasta water."},{"text":"Finely chop 2 ripe tomatoes (120g), 1/2 small onion (35g), and mince 2 cloves garlic."},{"text":"Heat 12ml cooking oil in a pan on medium heat. Sauté garlic and onions for 2 minutes until soft.","timer_seconds":120},{"text":"Add chopped tomatoes, 1/2 tsp salt, and a pinch of sugar; cook for 4 minutes, crushing tomatoes until a rich sauce forms.","timer_seconds":240},{"text":"Pour in 3 tbsp reserved pasta water and simmer for 1 minute until glossy.","timer_seconds":60},{"text":"Toss drained pasta into the sauce for 90 seconds until thoroughly coated.","timer_seconds":90},{"text":"Fold 50g fresh baby spinach directly into the hot pasta sauce for 60 seconds until gently wilted.","timer_seconds":60}]'::jsonb, '{"kcal":467,"protein":14.5,"carbs":72.7,"fats":13.8,"fiber":6}'::jsonb, 37, 366, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=600&q=80', '🍝', 69),
(70, 'Tomato Basil Penne with Golden Paneer Cubes', 'Italian', 'broke', ARRAY['15-min','muscle-gain'], 15, ARRAY['1-pan','induction'], 1, '[{"text":"Boil 85g pasta in 1 liter salted boiling water for 8 minutes until al dente; reserve 60ml pasta water and drain.","timer_seconds":480,"tip":"⚠️ Where this goes wrong: Under-cooking tomatoes produces a watery, acidic sauce. Sauté tomatoes until broken down into a jammy consistency, then loosen with starchy pasta water."},{"text":"Finely chop 2 ripe tomatoes (120g), 1/2 small onion (35g), and mince 2 cloves garlic."},{"text":"Heat 12ml cooking oil in a pan on medium heat. Sauté garlic and onions for 2 minutes until soft.","timer_seconds":120},{"text":"Add chopped tomatoes, 1/2 tsp salt, and a pinch of sugar; cook for 4 minutes, crushing tomatoes until a rich sauce forms.","timer_seconds":240},{"text":"Pour in 3 tbsp reserved pasta water and simmer for 1 minute until glossy.","timer_seconds":60},{"text":"Toss drained pasta into the sauce for 90 seconds until thoroughly coated.","timer_seconds":90},{"text":"Sear 60g paneer cubes for 2 minutes in oil until golden, then toss into the rich tomato sauce.","timer_seconds":120}]'::jsonb, '{"kcal":629,"protein":23.8,"carbs":72.7,"fats":26.8,"fiber":4.9}'::jsonb, 57.5, 426, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=600&q=80', '🍝', 70),
(71, 'Truffle Fettuccine with Artisan Truffle Drizzle', 'Italian', 'balanced', ARRAY['15-min','muscle-gain'], 15, ARRAY['1-pan','induction'], 1, '[{"text":"Boil 90g fettuccine pasta in 1 liter well-salted water for 8 minutes until al dente; reserve 60ml pasta water, drain.","timer_seconds":480,"tip":"⚠️ Where this goes wrong: Sautéing truffle oil in high heat destroys its delicate, earthy aroma instantly. Always pull the pan completely off the heat before swirling the oil in."},{"text":"Clean 90g button mushrooms with a cloth and slice thinly; mince 2 cloves garlic."},{"text":"Melt 15g butter in a wide skillet on medium heat (600W). Add garlic; cook 30 seconds until fragrant.","timer_seconds":30},{"text":"Add sliced mushrooms and a pinch of salt; sauté undisturbed for 3 minutes until caramelized and golden.","timer_seconds":180},{"text":"Pour in 3 tbsp reserved pasta water, swirling with mushroom juices to form a rich emulsion.","timer_seconds":45},{"text":"Add drained fettuccine, remove pan from heat completely, drizzle 6ml truffle oil, and toss with black pepper.","timer_seconds":60},{"text":"Drizzle an extra 4ml artisan truffle oil and cracked black pepper over the plated pasta for intense aroma."}]'::jsonb, '{"kcal":547,"protein":15.1,"carbs":69.5,"fats":23.8,"fiber":3.9}'::jsonb, 106.3, 716, 'https://images.unsplash.com/photo-1621996346565-e3d5d6281691?auto=format&fit=crop&w=600&q=80', '🍝', 71),
