(78, 'Ramen Quick Pot with Soft Boiled Egg', 'Pan-Asian', 'broke', ARRAY['15-min','fat-loss'], 12, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Pour 350ml water into an electric kettle or small pot and bring to a rolling boil.","timer_seconds":90,"tip":"⚠️ Where this goes wrong: Boiling noodles longer than 3 minutes leaves a limp, soggy texture. Cook noodles for 2.5 minutes max so strands stay springy and firm in hot broth."},{"text":"Add 1/2 tsp grated ginger, 1 minced garlic clove, and sliced green chilli to the bubbling broth.","timer_seconds":30},{"text":"Stir in 12ml soy sauce and half the instant tastemaker noodle seasoning.","timer_seconds":30},{"text":"Drop in 1 noodle cake (70g); simmer on medium heat for 2.5 minutes, loosening strands with a fork.","timer_seconds":150},{"text":"Pour springy noodles and aromatic steaming broth into a wide deep bowl.","timer_seconds":20},{"text":"Boil 1 egg for 6.5 minutes, plunge into cold water, peel, halve, and float in broth for jammy yolk.","timer_seconds":390}]'::jsonb, '{"kcal":401,"protein":14.8,"carbs":48.9,"fats":16.6,"fiber":2.9}'::jsonb, 29, 225, 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=600&q=80', '🍜', 78),
