(85, 'Teriyaki Stir Fry with Pan-Seared Tofu & Rice', 'Pan-Asian', 'broke', ARRAY['15-min'], 14, ARRAY['1-pan','induction'], 1, '[{"text":"In a small bowl, whisk 25ml soy sauce, 1 tsp sugar, 1 tsp minced ginger, 1 tsp minced garlic, and 2 tbsp water.","timer_seconds":40,"tip":"⚠️ Where this goes wrong: Stir-frying on low heat causes vegetables to weep water and steam into limp mush. Keep induction heat high and the pan moving for charred crispness."},{"text":"Slice 1/2 onion (45g) and 1/2 green bell pepper (45g) into thin strips."},{"text":"Heat 10ml cooking oil in a wide skillet or wok on high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add sliced onions and capsicum; stir-fry vigorously for 2 minutes until edges are charred but crisp.","timer_seconds":120},{"text":"Pour in the teriyaki sauce; it will bubble up and reduce to a shiny, sticky glaze within 60 seconds.","timer_seconds":60},{"text":"Toss vegetables to coat thoroughly in the savory-sweet glaze and transfer to a bowl.","timer_seconds":30},{"text":"Pan-fry 90g cubed tofu in 1 tsp oil for 3 minutes until golden, glaze in teriyaki, serve over 120g rice.","timer_seconds":180}]'::jsonb, '{"kcal":429,"protein":14.8,"carbs":60.9,"fats":15,"fiber":3.2}'::jsonb, 52.1, 435, 'https://images.unsplash.com/photo-1514944298352-f6700c3b0369?auto=format&fit=crop&w=600&q=80', '🥢', 85),
