(87, 'Teriyaki Stir Fry with Button Mushrooms & Corn', 'Pan-Asian', 'broke', ARRAY['15-min'], 14, ARRAY['1-pan','induction'], 1, '[{"text":"In a small bowl, whisk 25ml soy sauce, 1 tsp sugar, 1 tsp minced ginger, 1 tsp minced garlic, and 2 tbsp water.","timer_seconds":40,"tip":"⚠️ Where this goes wrong: Stir-frying on low heat causes vegetables to weep water and steam into limp mush. Keep induction heat high and the pan moving for charred crispness."},{"text":"Slice 1/2 onion (45g) and 1/2 green bell pepper (45g) into thin strips."},{"text":"Heat 10ml cooking oil in a wide skillet or wok on high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add sliced onions and capsicum; stir-fry vigorously for 2 minutes until edges are charred but crisp.","timer_seconds":120},{"text":"Pour in the teriyaki sauce; it will bubble up and reduce to a shiny, sticky glaze within 60 seconds.","timer_seconds":60},{"text":"Toss vegetables to coat thoroughly in the savory-sweet glaze and transfer to a bowl.","timer_seconds":30},{"text":"Sauté 70g mushrooms and 35g sweet corn in the teriyaki pan for 2.5 minutes until caramelized.","timer_seconds":150}]'::jsonb, '{"kcal":191,"protein":6.7,"carbs":20.1,"fats":10.9,"fiber":3.8}'::jsonb, 47.3, 410, 'https://images.unsplash.com/photo-1514944298352-f6700c3b0369?auto=format&fit=crop&w=600&q=80', '🥢', 87),
(88, 'Teriyaki Stir Fry with Steamed Quinoa', 'Pan-Asian', 'broke', ARRAY['15-min'], 14, ARRAY['1-pan','induction'], 1, '[{"text":"In a small bowl, whisk 25ml soy sauce, 1 tsp sugar, 1 tsp minced ginger, 1 tsp minced garlic, and 2 tbsp water.","timer_seconds":40,"tip":"⚠️ Where this goes wrong: Stir-frying on low heat causes vegetables to weep water and steam into limp mush. Keep induction heat high and the pan moving for charred crispness."},{"text":"Slice 1/2 onion (45g) and 1/2 green bell pepper (45g) into thin strips."},{"text":"Heat 10ml cooking oil in a wide skillet or wok on high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add sliced onions and capsicum; stir-fry vigorously for 2 minutes until edges are charred but crisp.","timer_seconds":120},{"text":"Pour in the teriyaki sauce; it will bubble up and reduce to a shiny, sticky glaze within 60 seconds.","timer_seconds":60},{"text":"Toss vegetables to coat thoroughly in the savory-sweet glaze and transfer to a bowl.","timer_seconds":30},{"text":"Layer 60g cooked fluffy quinoa into the bowl and ladle the glossy stir-fry over it.","timer_seconds":30}]'::jsonb, '{"kcal":329,"protein":10.5,"carbs":43.3,"fats":13.3,"fiber":5.7}'::jsonb, 38.5, 500, 'https://images.unsplash.com/photo-1514944298352-f6700c3b0369?auto=format&fit=crop&w=600&q=80', '🥢', 88),
(89, 'Teriyaki Stir Fry with Toasted Peanuts & Chilli', 'Pan-Asian', 'broke', ARRAY['15-min'], 14, ARRAY['1-pan','induction'], 1, '[{"text":"In a small bowl, whisk 25ml soy sauce, 1 tsp sugar, 1 tsp minced ginger, 1 tsp minced garlic, and 2 tbsp water.","timer_seconds":40,"tip":"⚠️ Where this goes wrong: Stir-frying on low heat causes vegetables to weep water and steam into limp mush. Keep induction heat high and the pan moving for charred crispness."},{"text":"Slice 1/2 onion (45g) and 1/2 green bell pepper (45g) into thin strips."},{"text":"Heat 10ml cooking oil in a wide skillet or wok on high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add sliced onions and capsicum; stir-fry vigorously for 2 minutes until edges are charred but crisp.","timer_seconds":120},{"text":"Pour in the teriyaki sauce; it will bubble up and reduce to a shiny, sticky glaze within 60 seconds.","timer_seconds":60},{"text":"Toss vegetables to coat thoroughly in the savory-sweet glaze and transfer to a bowl.","timer_seconds":30},{"text":"Toast 25g peanuts with sliced green chilli in 1/2 tsp oil for 90 seconds, scatter over stir fry.","timer_seconds":90}]'::jsonb, '{"kcal":288,"protein":10,"carbs":15.6,"fats":22.6,"fiber":4.3}'::jsonb, 24.4, 357, 'https://images.unsplash.com/photo-1514944298352-f6700c3b0369?auto=format&fit=crop&w=600&q=80', '🥢', 89),
(90, 'Teriyaki Stir Fry with Crispy Soya Chunks', 'Pan-Asian', 'broke', ARRAY['15-min','high-protein','fat-loss'], 14, ARRAY['1-pan','induction'], 1, '[{"text":"In a small bowl, whisk 25ml soy sauce, 1 tsp sugar, 1 tsp minced ginger, 1 tsp minced garlic, and 2 tbsp water.","timer_seconds":40,"tip":"⚠️ Where this goes wrong: Stir-frying on low heat causes vegetables to weep water and steam into limp mush. Keep induction heat high and the pan moving for charred crispness."},{"text":"Slice 1/2 onion (45g) and 1/2 green bell pepper (45g) into thin strips."},{"text":"Heat 10ml cooking oil in a wide skillet or wok on high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add sliced onions and capsicum; stir-fry vigorously for 2 minutes until edges are charred but crisp.","timer_seconds":120},{"text":"Pour in the teriyaki sauce; it will bubble up and reduce to a shiny, sticky glaze within 60 seconds.","timer_seconds":60},{"text":"Toss vegetables to coat thoroughly in the savory-sweet glaze and transfer to a bowl.","timer_seconds":30},{"text":"Soak 45g soya chunks, squeeze dry, pan-fry until crunchy, and glaze in sticky teriyaki.","timer_seconds":240}]'::jsonb, '{"kcal":300,"protein":26.8,"carbs":26,"fats":10.5,"fiber":8}'::jsonb, 29.1, 350, 'https://images.unsplash.com/photo-1514944298352-f6700c3b0369?auto=format&fit=crop&w=600&q=80', '🥢', 90),
(91, 'Teriyaki Stir Fry with Sunny Side Egg', 'Pan-Asian', 'broke', ARRAY['15-min'], 14, ARRAY['1-pan','induction'], 1, '[{"text":"In a small bowl, whisk 25ml soy sauce, 1 tsp sugar, 1 tsp minced ginger, 1 tsp minced garlic, and 2 tbsp water.","timer_seconds":40,"tip":"⚠️ Where this goes wrong: Stir-frying on low heat causes vegetables to weep water and steam into limp mush. Keep induction heat high and the pan moving for charred crispness."},{"text":"Slice 1/2 onion (45g) and 1/2 green bell pepper (45g) into thin strips."},{"text":"Heat 10ml cooking oil in a wide skillet or wok on high heat (1000W) until shimmering.","timer_seconds":45},{"text":"Add sliced onions and capsicum; stir-fry vigorously for 2 minutes until edges are charred but crisp.","timer_seconds":120},{"text":"Pour in the teriyaki sauce; it will bubble up and reduce to a shiny, sticky glaze within 60 seconds.","timer_seconds":60},{"text":"Toss vegetables to coat thoroughly in the savory-sweet glaze and transfer to a bowl.","timer_seconds":30},{"text":"Fry 1 egg in oil with crispy lacy edges for 2 minutes; crown the stir-fry bowl.","timer_seconds":120}]'::jsonb, '{"kcal":217,"protein":9.7,"carbs":11.6,"fats":15.3,"fiber":2.2}'::jsonb, 27.6, 357, 'https://images.unsplash.com/photo-1514944298352-f6700c3b0369?auto=format&fit=crop&w=600&q=80', '🥢', 91),
(92, 'Gourmet Sushi Bowl with Norwegian Teriyaki Salmon', 'Pan-Asian', 'hifi', ARRAY['high-protein','muscle-gain'], 16, ARRAY['no-cook','hostel-friendly'], 1, '[{"text":"Take 130g room-temperature cooked rice; toss with 1 tsp lemon juice, 1/3 tsp salt, and 1/3 tsp sugar.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Assembling the bowl over piping hot rice wilts fresh veggies and warms the avocado into unpleasant mush. Let cooked rice cool to room temperature first."},{"text":"Spoon the seasoned rice into a shallow broad bowl and level gently with a moist spoon.","timer_seconds":30},{"text":"Cut 1/2 ripe avocado into clean thin slices; fan out over one quarter of the bowl."},{"text":"Slice 35g capsicum into crisp matchsticks and arrange in the adjacent quarter."},{"text":"Mix 15ml soy sauce with 1/2 tsp lemon juice in a small cup for dressing.","timer_seconds":30},{"text":"Drizzle the tangy soy dressing across the rice and avocado.","timer_seconds":20},{"text":"Sear 130g salmon fillet in pan for 3.5 mins skin-down, flip 2 mins with soy glaze, and flake over rice.","timer_seconds":330}]'::jsonb, '{"kcal":672,"protein":35,"carbs":67.6,"fats":28.6,"fiber":7.5}'::jsonb, 259.1, 642, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?auto=format&fit=crop&w=600&q=80', '🍣', 92),
