(95, 'Gourmet Sushi Bowl with Sweet Corn & Edamame', 'Pan-Asian', 'balanced', ARRAY['15-min'], 12, ARRAY['no-cook','hostel-friendly'], 1, '[{"text":"Take 130g room-temperature cooked rice; toss with 1 tsp lemon juice, 1/3 tsp salt, and 1/3 tsp sugar.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Assembling the bowl over piping hot rice wilts fresh veggies and warms the avocado into unpleasant mush. Let cooked rice cool to room temperature first."},{"text":"Spoon the seasoned rice into a shallow broad bowl and level gently with a moist spoon.","timer_seconds":30},{"text":"Cut 1/2 ripe avocado into clean thin slices; fan out over one quarter of the bowl."},{"text":"Slice 35g capsicum into crisp matchsticks and arrange in the adjacent quarter."},{"text":"Mix 15ml soy sauce with 1/2 tsp lemon juice in a small cup for dressing.","timer_seconds":30},{"text":"Drizzle the tangy soy dressing across the rice and avocado.","timer_seconds":20},{"text":"Steam 45g sweet corn kernels, toss with a touch of oil, and arrange beside the vegetables.","timer_seconds":60}]'::jsonb, '{"kcal":435,"protein":9.6,"carbs":75.6,"fats":12.2,"fiber":8.7}'::jsonb, 65.7, 302, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?auto=format&fit=crop&w=600&q=80', '🍣', 95),
(96, 'Gourmet Sushi Bowl with Soft Boiled Jammy Egg', 'Pan-Asian', 'balanced', ARRAY['15-min'], 12, ARRAY['no-cook','hostel-friendly'], 1, '[{"text":"Take 130g room-temperature cooked rice; toss with 1 tsp lemon juice, 1/3 tsp salt, and 1/3 tsp sugar.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Assembling the bowl over piping hot rice wilts fresh veggies and warms the avocado into unpleasant mush. Let cooked rice cool to room temperature first."},{"text":"Spoon the seasoned rice into a shallow broad bowl and level gently with a moist spoon.","timer_seconds":30},{"text":"Cut 1/2 ripe avocado into clean thin slices; fan out over one quarter of the bowl."},{"text":"Slice 35g capsicum into crisp matchsticks and arrange in the adjacent quarter."},{"text":"Mix 15ml soy sauce with 1/2 tsp lemon juice in a small cup for dressing.","timer_seconds":30},{"text":"Drizzle the tangy soy dressing across the rice and avocado.","timer_seconds":20},{"text":"Boil 1 egg for 6.5 minutes, peel, slice in half, and set with golden yolk facing up.","timer_seconds":390}]'::jsonb, '{"kcal":469,"protein":14.5,"carbs":67.5,"fats":16.6,"fiber":7.5}'::jsonb, 67.2, 314, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?auto=format&fit=crop&w=600&q=80', '🍣', 96),
(97, 'Gourmet Sushi Bowl with Sautéed Teriyaki Mushrooms', 'Pan-Asian', 'balanced', ARRAY['15-min'], 12, ARRAY['no-cook','hostel-friendly'], 1, '[{"text":"Take 130g room-temperature cooked rice; toss with 1 tsp lemon juice, 1/3 tsp salt, and 1/3 tsp sugar.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Assembling the bowl over piping hot rice wilts fresh veggies and warms the avocado into unpleasant mush. Let cooked rice cool to room temperature first."},{"text":"Spoon the seasoned rice into a shallow broad bowl and level gently with a moist spoon.","timer_seconds":30},{"text":"Cut 1/2 ripe avocado into clean thin slices; fan out over one quarter of the bowl."},{"text":"Slice 35g capsicum into crisp matchsticks and arrange in the adjacent quarter."},{"text":"Mix 15ml soy sauce with 1/2 tsp lemon juice in a small cup for dressing.","timer_seconds":30},{"text":"Drizzle the tangy soy dressing across the rice and avocado.","timer_seconds":20},{"text":"Sauté 70g mushrooms in soy sauce and butter for 3 minutes until glazed; spoon over rice.","timer_seconds":180}]'::jsonb, '{"kcal":448,"protein":10.4,"carbs":69.4,"fats":15.9,"fiber":8.2}'::jsonb, 84.1, 383, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?auto=format&fit=crop&w=600&q=80', '🍣', 97),
(98, 'Gourmet Sushi Bowl with Steamed Fluffy Quinoa', 'Pan-Asian', 'balanced', ARRAY['15-min','muscle-gain'], 12, ARRAY['no-cook','hostel-friendly'], 1, '[{"text":"Take 130g room-temperature cooked rice; toss with 1 tsp lemon juice, 1/3 tsp salt, and 1/3 tsp sugar.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Assembling the bowl over piping hot rice wilts fresh veggies and warms the avocado into unpleasant mush. Let cooked rice cool to room temperature first."},{"text":"Spoon the seasoned rice into a shallow broad bowl and level gently with a moist spoon.","timer_seconds":30},{"text":"Cut 1/2 ripe avocado into clean thin slices; fan out over one quarter of the bowl."},{"text":"Slice 35g capsicum into crisp matchsticks and arrange in the adjacent quarter."},{"text":"Mix 15ml soy sauce with 1/2 tsp lemon juice in a small cup for dressing.","timer_seconds":30},{"text":"Drizzle the tangy soy dressing across the rice and avocado.","timer_seconds":20},{"text":"Substitute half the rice with 50g fluffy steamed quinoa tossed with sea salt and lemon.","timer_seconds":30}]'::jsonb, '{"kcal":562,"protein":14.5,"carbs":96,"fats":14.4,"fiber":10.6}'::jsonb, 76.1, 457, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?auto=format&fit=crop&w=600&q=80', '🍣', 98),
(99, 'Bean & Corn Quesadilla with Fresh Tomato Salsa', 'Mexican', 'broke', ARRAY['15-min'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"In a bowl, mix 55g cooked black beans and 40g sweet corn kernels with 1/4 tsp cumin, 1/4 tsp chilli, and 1/3 tsp salt.","tip":"⚠️ Where this goes wrong: Cranking up high heat burns the tortilla before the cheese has time to melt inside. Keep heat medium-low so the bread toasts golden while cheese turns gooey."},{"text":"Mash lightly with a fork so the mixture binds slightly."},{"text":"Heat a flat pan on medium-low heat (400W); melt 8g butter.","timer_seconds":30},{"text":"Place flatbread or tortilla on the pan; lay 1 cheese slice on one half of the bread."},{"text":"Spread the bean-corn filling over the cheese and fold the other half over to create a half-moon.","timer_seconds":30},{"text":"Toast for 2 minutes until golden brown, flip gently, and cook 1.5 minutes until cheese is molten.","timer_seconds":210},{"text":"Slice into wedges and enjoy while cheese is gooey and stretchy.","timer_seconds":20},{"text":"Dice 1/2 tomato and 1/4 onion with chopped coriander, green chilli, and lemon; serve on the side.","timer_seconds":90}]'::jsonb, '{"kcal":467,"protein":21.5,"carbs":67.7,"fats":14.5,"fiber":12.9}'::jsonb, 46.1, 427, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=600&q=80', '🌮', 99),
(100, 'Bean & Corn Quesadilla with Sautéed Capsicum & Onions', 'Mexican', 'broke', ARRAY['15-min'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"In a bowl, mix 55g cooked black beans and 40g sweet corn kernels with 1/4 tsp cumin, 1/4 tsp chilli, and 1/3 tsp salt.","tip":"⚠️ Where this goes wrong: Cranking up high heat burns the tortilla before the cheese has time to melt inside. Keep heat medium-low so the bread toasts golden while cheese turns gooey."},{"text":"Mash lightly with a fork so the mixture binds slightly."},{"text":"Heat a flat pan on medium-low heat (400W); melt 8g butter.","timer_seconds":30},{"text":"Place flatbread or tortilla on the pan; lay 1 cheese slice on one half of the bread."},{"text":"Spread the bean-corn filling over the cheese and fold the other half over to create a half-moon.","timer_seconds":30},{"text":"Toast for 2 minutes until golden brown, flip gently, and cook 1.5 minutes until cheese is molten.","timer_seconds":210},{"text":"Slice into wedges and enjoy while cheese is gooey and stretchy.","timer_seconds":20},{"text":"Stir-fry 35g capsicum and onion strips until charred, tuck inside the quesadilla filling.","timer_seconds":120}]'::jsonb, '{"kcal":451,"protein":20.9,"carbs":63.5,"fats":14.4,"fiber":11.9}'::jsonb, 44.6, 439, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=600&q=80', '🌮', 100)
INSERT INTO public.recipes (id, title, cuisine, budget_tier, goals, minutes, equipment_tags, servings, steps, macros, cost_per_serving, cost_full_pack, image_url, emoji, gradient_seed) VALUES
(101, 'Bean & Corn Quesadilla with Double Melting Cheese', 'Mexican', 'broke', ARRAY['15-min','high-protein','muscle-gain'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"In a bowl, mix 55g cooked black beans and 40g sweet corn kernels with 1/4 tsp cumin, 1/4 tsp chilli, and 1/3 tsp salt.","tip":"⚠️ Where this goes wrong: Cranking up high heat burns the tortilla before the cheese has time to melt inside. Keep heat medium-low so the bread toasts golden while cheese turns gooey."},{"text":"Mash lightly with a fork so the mixture binds slightly."},{"text":"Heat a flat pan on medium-low heat (400W); melt 8g butter.","timer_seconds":30},{"text":"Place flatbread or tortilla on the pan; lay 1 cheese slice on one half of the bread."},{"text":"Spread the bean-corn filling over the cheese and fold the other half over to create a half-moon.","timer_seconds":30},{"text":"Toast for 2 minutes until golden brown, flip gently, and cook 1.5 minutes until cheese is molten.","timer_seconds":210},{"text":"Slice into wedges and enjoy while cheese is gooey and stretchy.","timer_seconds":20},{"text":"Add an extra full slice of cheddar/processed cheese for extreme melted cheese pull."}]'::jsonb, '{"kcal":507,"protein":24.5,"carbs":61.9,"fats":19.8,"fiber":11.2}'::jsonb, 51.2, 407, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=600&q=80', '🌮', 101),
(102, 'Bean & Corn Quesadilla with Smashed Guacamole', 'Mexican', 'balanced', ARRAY['15-min','muscle-gain'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"In a bowl, mix 55g cooked black beans and 40g sweet corn kernels with 1/4 tsp cumin, 1/4 tsp chilli, and 1/3 tsp salt.","tip":"⚠️ Where this goes wrong: Cranking up high heat burns the tortilla before the cheese has time to melt inside. Keep heat medium-low so the bread toasts golden while cheese turns gooey."},{"text":"Mash lightly with a fork so the mixture binds slightly."},{"text":"Heat a flat pan on medium-low heat (400W); melt 8g butter.","timer_seconds":30},{"text":"Place flatbread or tortilla on the pan; lay 1 cheese slice on one half of the bread."},{"text":"Spread the bean-corn filling over the cheese and fold the other half over to create a half-moon.","timer_seconds":30},{"text":"Toast for 2 minutes until golden brown, flip gently, and cook 1.5 minutes until cheese is molten.","timer_seconds":210},{"text":"Slice into wedges and enjoy while cheese is gooey and stretchy.","timer_seconds":20},{"text":"Mash 1/2 avocado with salt, lemon juice, and a pinch of chilli; spoon over warm wedges.","timer_seconds":60}]'::jsonb, '{"kcal":562,"protein":22,"carbs":67.4,"fats":25.3,"fiber":16.2}'::jsonb, 82.7, 492, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=600&q=80', '🌮', 102),
(103, 'Bean & Corn Quesadilla with Shredded Chicken Breast', 'Mexican', 'balanced', ARRAY['15-min','high-protein','muscle-gain'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"In a bowl, mix 55g cooked black beans and 40g sweet corn kernels with 1/4 tsp cumin, 1/4 tsp chilli, and 1/3 tsp salt.","tip":"⚠️ Where this goes wrong: Cranking up high heat burns the tortilla before the cheese has time to melt inside. Keep heat medium-low so the bread toasts golden while cheese turns gooey."},{"text":"Mash lightly with a fork so the mixture binds slightly."},{"text":"Heat a flat pan on medium-low heat (400W); melt 8g butter.","timer_seconds":30},{"text":"Place flatbread or tortilla on the pan; lay 1 cheese slice on one half of the bread."},{"text":"Spread the bean-corn filling over the cheese and fold the other half over to create a half-moon.","timer_seconds":30},{"text":"Toast for 2 minutes until golden brown, flip gently, and cook 1.5 minutes until cheese is molten.","timer_seconds":210},{"text":"Slice into wedges and enjoy while cheese is gooey and stretchy.","timer_seconds":20},{"text":"Tuck 60g cooked shredded chicken breast seasoned with cumin and chilli inside the quesadilla.","timer_seconds":120}]'::jsonb, '{"kcal":541,"protein":39.1,"carbs":61.4,"fats":16.5,"fiber":11.2}'::jsonb, 60.6, 577, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=600&q=80', '🌮', 103),
(104, 'Bean & Corn Quesadilla with Tangy Curd Sour Cream', 'Mexican', 'broke', ARRAY['15-min'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"In a bowl, mix 55g cooked black beans and 40g sweet corn kernels with 1/4 tsp cumin, 1/4 tsp chilli, and 1/3 tsp salt.","tip":"⚠️ Where this goes wrong: Cranking up high heat burns the tortilla before the cheese has time to melt inside. Keep heat medium-low so the bread toasts golden while cheese turns gooey."},{"text":"Mash lightly with a fork so the mixture binds slightly."},{"text":"Heat a flat pan on medium-low heat (400W); melt 8g butter.","timer_seconds":30},{"text":"Place flatbread or tortilla on the pan; lay 1 cheese slice on one half of the bread."},{"text":"Spread the bean-corn filling over the cheese and fold the other half over to create a half-moon.","timer_seconds":30},{"text":"Toast for 2 minutes until golden brown, flip gently, and cook 1.5 minutes until cheese is molten.","timer_seconds":210},{"text":"Slice into wedges and enjoy while cheese is gooey and stretchy.","timer_seconds":20},{"text":"Whisk 50g thick curd with lemon juice and salt to make a cooling protein dip on the side.","timer_seconds":30}]'::jsonb, '{"kcal":472,"protein":22.3,"carbs":63.7,"fats":15.8,"fiber":11.2}'::jsonb, 44.5, 442, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=600&q=80', '🌮', 104),
(105, 'Bean & Corn Quesadilla with Spicy Soya Keema', 'Mexican', 'broke', ARRAY['15-min','high-protein','muscle-gain'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"In a bowl, mix 55g cooked black beans and 40g sweet corn kernels with 1/4 tsp cumin, 1/4 tsp chilli, and 1/3 tsp salt.","tip":"⚠️ Where this goes wrong: Cranking up high heat burns the tortilla before the cheese has time to melt inside. Keep heat medium-low so the bread toasts golden while cheese turns gooey."},{"text":"Mash lightly with a fork so the mixture binds slightly."},{"text":"Heat a flat pan on medium-low heat (400W); melt 8g butter.","timer_seconds":30},{"text":"Place flatbread or tortilla on the pan; lay 1 cheese slice on one half of the bread."},{"text":"Spread the bean-corn filling over the cheese and fold the other half over to create a half-moon.","timer_seconds":30},{"text":"Toast for 2 minutes until golden brown, flip gently, and cook 1.5 minutes until cheese is molten.","timer_seconds":210},{"text":"Slice into wedges and enjoy while cheese is gooey and stretchy.","timer_seconds":20},{"text":"Add 35g cooked spiced soya mince to the quesadilla filling for 18g plant protein.","timer_seconds":90}]'::jsonb, '{"kcal":562,"protein":38.7,"carbs":72.9,"fats":14.5,"fiber":15.8}'::jsonb, 48, 452, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=600&q=80', '🌮', 105),
(106, 'Chipotle Protein Bowl with Grilled Chicken Breast', 'Mexican', 'balanced', ARRAY['high-protein','muscle-gain'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Layer 130g warm cooked rice into a wide bowl as the base.","timer_seconds":30,"tip":"⚠️ Where this goes wrong: Spooning unseasoned, cold canned beans over rice. Always warm beans in a skillet with cumin, chilli, and salt so they absorb deep Mexican flavors."},{"text":"Heat 8ml oil in a skillet on medium heat; add 65g black beans, 45g sweet corn, 1/4 tsp cumin, and 1/3 tsp salt.","timer_seconds":30},{"text":"Sauté beans and corn for 2 minutes until hot and aromatic, then spoon into one quadrant of the bowl.","timer_seconds":120},{"text":"Dice 50g tomato and 35g onion; toss with chopped coriander, squeeze of lemon, and salt to make fresh salsa.","timer_seconds":90},{"text":"Spoon the fresh tomato-onion salsa into the adjacent quadrant.","timer_seconds":20},{"text":"Drizzle 1 tsp olive or cooking oil and squeeze fresh lemon over the assembled bowl.","timer_seconds":20},{"text":"Rub 120g chicken breast with cumin, chilli powder, and oil; sear 4.5 minutes, slice and fan over bowl.","timer_seconds":270}]'::jsonb, '{"kcal":813,"protein":58.8,"carbs":112.9,"fats":14.5,"fiber":14.1}'::jsonb, 72.7, 601, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80', '🌯', 106),
