(111, 'Chipotle Protein Bowl with Greek Yogurt Lime Crema', 'Mexican', 'broke', ARRAY['15-min','high-protein','muscle-gain'], 15, ARRAY['1-pan','induction'], 1, '[{"text":"Layer 130g warm cooked rice into a wide bowl as the base.","timer_seconds":30,"tip":"⚠️ Where this goes wrong: Spooning unseasoned, cold canned beans over rice. Always warm beans in a skillet with cumin, chilli, and salt so they absorb deep Mexican flavors."},{"text":"Heat 8ml oil in a skillet on medium heat; add 65g black beans, 45g sweet corn, 1/4 tsp cumin, and 1/3 tsp salt.","timer_seconds":30},{"text":"Sauté beans and corn for 2 minutes until hot and aromatic, then spoon into one quadrant of the bowl.","timer_seconds":120},{"text":"Dice 50g tomato and 35g onion; toss with chopped coriander, squeeze of lemon, and salt to make fresh salsa.","timer_seconds":90},{"text":"Spoon the fresh tomato-onion salsa into the adjacent quadrant.","timer_seconds":20},{"text":"Drizzle 1 tsp olive or cooking oil and squeeze fresh lemon over the assembled bowl.","timer_seconds":20},{"text":"Whisk 50g Greek yogurt with lime juice and a pinch of salt; drizzle as cooling cream dressing.","timer_seconds":40}]'::jsonb, '{"kcal":664,"protein":26.1,"carbs":114.9,"fats":12.6,"fiber":14.1}'::jsonb, 43.1, 521, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80', '🌯', 111),
(112, 'Chipotle Protein Bowl with Fluffy Quinoa Base', 'Mexican', 'broke', ARRAY['15-min','high-protein','muscle-gain'], 15, ARRAY['1-pan','induction'], 1, '[{"text":"Layer 130g warm cooked rice into a wide bowl as the base.","timer_seconds":30,"tip":"⚠️ Where this goes wrong: Spooning unseasoned, cold canned beans over rice. Always warm beans in a skillet with cumin, chilli, and salt so they absorb deep Mexican flavors."},{"text":"Heat 8ml oil in a skillet on medium heat; add 65g black beans, 45g sweet corn, 1/4 tsp cumin, and 1/3 tsp salt.","timer_seconds":30},{"text":"Sauté beans and corn for 2 minutes until hot and aromatic, then spoon into one quadrant of the bowl.","timer_seconds":120},{"text":"Dice 50g tomato and 35g onion; toss with chopped coriander, squeeze of lemon, and salt to make fresh salsa.","timer_seconds":90},{"text":"Spoon the fresh tomato-onion salsa into the adjacent quadrant.","timer_seconds":20},{"text":"Drizzle 1 tsp olive or cooking oil and squeeze fresh lemon over the assembled bowl.","timer_seconds":20},{"text":"Swap rice for 50g fluffy cooked quinoa tossed with lime juice and coriander.","timer_seconds":30}]'::jsonb, '{"kcal":799,"protein":28.7,"carbs":145,"fats":13.2,"fiber":17.6}'::jsonb, 51.4, 626, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80', '🌯', 112),
(113, 'Artisan Fajita Skillet with Sizzling Chicken Breast Strips', 'Mexican', 'balanced', ARRAY['high-protein','fat-loss'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Cut 1 large bell pepper (90g) and 1 medium onion (70g) into long 1/2cm strips; mince 2 cloves garlic.","tip":"⚠️ Where this goes wrong: Moving peppers and onions constantly in the pan prevents them from searing. Let veggies sit motionless on the screaming hot skillet for 60 seconds to get signature blistered char."},{"text":"In a cup, mix 1/2 tsp cumin, 1/2 tsp chilli powder, 1/2 tsp salt, and 1 tbsp lemon juice.","timer_seconds":30},{"text":"Heat 12ml cooking oil in a wide heavy skillet on high induction heat (1000W) until smoking hot.","timer_seconds":60},{"text":"Drop in sliced peppers, onions, and minced garlic in a single layer.","timer_seconds":20},{"text":"Leave untouched for 60 seconds, then toss and sear for another 2.5 minutes until charred and blistered.","timer_seconds":210},{"text":"Pour the spiced lemon glaze over the sizzling pan; toss vigorously for 30 seconds as steam deglazes.","timer_seconds":30},{"text":"Sear 130g spiced chicken breast strips on high heat for 4 minutes before tossing with vegetables.","timer_seconds":240}]'::jsonb, '{"kcal":402,"protein":43.2,"carbs":18,"fats":17.9,"fiber":4.8}'::jsonb, 65.4, 487, 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=600&q=80', '🥩', 113),
