(116, 'Artisan Fajita Skillet with Sliced Avocado & Lime', 'Mexican', 'balanced', ARRAY['15-min'], 15, ARRAY['1-pan','induction'], 1, '[{"text":"Cut 1 large bell pepper (90g) and 1 medium onion (70g) into long 1/2cm strips; mince 2 cloves garlic.","tip":"⚠️ Where this goes wrong: Moving peppers and onions constantly in the pan prevents them from searing. Let veggies sit motionless on the screaming hot skillet for 60 seconds to get signature blistered char."},{"text":"In a cup, mix 1/2 tsp cumin, 1/2 tsp chilli powder, 1/2 tsp salt, and 1 tbsp lemon juice.","timer_seconds":30},{"text":"Heat 12ml cooking oil in a wide heavy skillet on high induction heat (1000W) until smoking hot.","timer_seconds":60},{"text":"Drop in sliced peppers, onions, and minced garlic in a single layer.","timer_seconds":20},{"text":"Leave untouched for 60 seconds, then toss and sear for another 2.5 minutes until charred and blistered.","timer_seconds":210},{"text":"Pour the spiced lemon glaze over the sizzling pan; toss vigorously for 30 seconds as steam deglazes.","timer_seconds":30},{"text":"Arrange 1/2 sliced creamy avocado and charred lime wedges over the hot skillet.","timer_seconds":40}]'::jsonb, '{"kcal":307,"protein":4.4,"carbs":24,"fats":24.2,"fiber":9.8}'::jsonb, 63.7, 402, 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=600&q=80', '🥩', 116),
