(118, 'Artisan Fajita Skillet with Sautéed Garlic Mushrooms', 'Mexican', 'broke', ARRAY['15-min'], 15, ARRAY['1-pan','induction'], 1, '[{"text":"Cut 1 large bell pepper (90g) and 1 medium onion (70g) into long 1/2cm strips; mince 2 cloves garlic.","tip":"⚠️ Where this goes wrong: Moving peppers and onions constantly in the pan prevents them from searing. Let veggies sit motionless on the screaming hot skillet for 60 seconds to get signature blistered char."},{"text":"In a cup, mix 1/2 tsp cumin, 1/2 tsp chilli powder, 1/2 tsp salt, and 1 tbsp lemon juice.","timer_seconds":30},{"text":"Heat 12ml cooking oil in a wide heavy skillet on high induction heat (1000W) until smoking hot.","timer_seconds":60},{"text":"Drop in sliced peppers, onions, and minced garlic in a single layer.","timer_seconds":20},{"text":"Leave untouched for 60 seconds, then toss and sear for another 2.5 minutes until charred and blistered.","timer_seconds":210},{"text":"Pour the spiced lemon glaze over the sizzling pan; toss vigorously for 30 seconds as steam deglazes.","timer_seconds":30},{"text":"Sauté 75g sliced button mushrooms in the skillet for 3 minutes until juicy and caramelized.","timer_seconds":180}]'::jsonb, '{"kcal":204,"protein":5.2,"carbs":20.5,"fats":13.4,"fiber":5.5}'::jsonb, 45.6, 382, 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=600&q=80', '🥩', 118),
(119, 'Artisan Fajita Skillet with Melting Cheddar Layer', 'Mexican', 'broke', ARRAY['15-min'], 15, ARRAY['1-pan','induction'], 1, '[{"text":"Cut 1 large bell pepper (90g) and 1 medium onion (70g) into long 1/2cm strips; mince 2 cloves garlic.","tip":"⚠️ Where this goes wrong: Moving peppers and onions constantly in the pan prevents them from searing. Let veggies sit motionless on the screaming hot skillet for 60 seconds to get signature blistered char."},{"text":"In a cup, mix 1/2 tsp cumin, 1/2 tsp chilli powder, 1/2 tsp salt, and 1 tbsp lemon juice.","timer_seconds":30},{"text":"Heat 12ml cooking oil in a wide heavy skillet on high induction heat (1000W) until smoking hot.","timer_seconds":60},{"text":"Drop in sliced peppers, onions, and minced garlic in a single layer.","timer_seconds":20},{"text":"Leave untouched for 60 seconds, then toss and sear for another 2.5 minutes until charred and blistered.","timer_seconds":210},{"text":"Pour the spiced lemon glaze over the sizzling pan; toss vigorously for 30 seconds as steam deglazes.","timer_seconds":30},{"text":"Lay 1 slice of cheddar over hot vegetables, cover pan for 45 seconds until bubbling.","timer_seconds":45}]'::jsonb, '{"kcal":252,"protein":6.9,"carbs":18.5,"fats":18.7,"fiber":4.8}'::jsonb, 32.2, 427, 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=600&q=80', '🥩', 119),
(120, 'Peanut Butter Oats with Fresh Banana Slices', 'Continental', 'broke', ARRAY['15-min','muscle-gain'], 8, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Place 50g rolled oats in a small pot or electric kettle.","timer_seconds":20,"tip":"⚠️ Where this goes wrong: Stirring peanut butter into rolling boiling milk causes the oil to separate and curdle. Turn off heat first, then stir in peanut butter until it melts into silky cream."},{"text":"Pour in 160ml milk (or 80ml milk + 80ml water) and a tiny pinch of salt.","timer_seconds":30},{"text":"Bring to a gentle simmer on medium-low heat, stirring with a spoon to prevent milk from scorching.","timer_seconds":120},{"text":"Cook for 2.5 minutes until oats thicken and absorb the milk.","timer_seconds":150},{"text":"Turn off heat completely. Add 25g peanut butter.","timer_seconds":20},{"text":"Stir vigorously for 40 seconds until peanut butter melts into velvety, creamy oats.","timer_seconds":40},{"text":"Pour into a bowl and let settle for 1 minute before topping.","timer_seconds":60},{"text":"Slice another 1/2 ripe banana into neat coins and arrange across the warm oatmeal.","timer_seconds":45}]'::jsonb, '{"kcal":530,"protein":20.9,"carbs":68.6,"fats":21.5,"fiber":9.4}'::jsonb, 37.1, 308, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=600&q=80', '🥣', 120),
(121, 'Peanut Butter Oats with Crunchy Roasted Peanuts', 'Continental', 'broke', ARRAY['15-min','high-protein','muscle-gain'], 8, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Place 50g rolled oats in a small pot or electric kettle.","timer_seconds":20,"tip":"⚠️ Where this goes wrong: Stirring peanut butter into rolling boiling milk causes the oil to separate and curdle. Turn off heat first, then stir in peanut butter until it melts into silky cream."},{"text":"Pour in 160ml milk (or 80ml milk + 80ml water) and a tiny pinch of salt.","timer_seconds":30},{"text":"Bring to a gentle simmer on medium-low heat, stirring with a spoon to prevent milk from scorching.","timer_seconds":120},{"text":"Cook for 2.5 minutes until oats thicken and absorb the milk.","timer_seconds":150},{"text":"Turn off heat completely. Add 25g peanut butter.","timer_seconds":20},{"text":"Stir vigorously for 40 seconds until peanut butter melts into velvety, creamy oats.","timer_seconds":40},{"text":"Pour into a bowl and let settle for 1 minute before topping.","timer_seconds":60},{"text":"Scatter 20g crushed roasted peanuts on top for contrasting salty crunch.","timer_seconds":20}]'::jsonb, '{"kcal":599,"protein":25.5,"carbs":60.4,"fats":31.2,"fiber":9.8}'::jsonb, 37.3, 348, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=600&q=80', '🥣', 121),
(122, 'Peanut Butter Oats with Crispy Granola Clusters', 'Continental', 'broke', ARRAY['15-min','muscle-gain'], 8, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Place 50g rolled oats in a small pot or electric kettle.","timer_seconds":20,"tip":"⚠️ Where this goes wrong: Stirring peanut butter into rolling boiling milk causes the oil to separate and curdle. Turn off heat first, then stir in peanut butter until it melts into silky cream."},{"text":"Pour in 160ml milk (or 80ml milk + 80ml water) and a tiny pinch of salt.","timer_seconds":30},{"text":"Bring to a gentle simmer on medium-low heat, stirring with a spoon to prevent milk from scorching.","timer_seconds":120},{"text":"Cook for 2.5 minutes until oats thicken and absorb the milk.","timer_seconds":150},{"text":"Turn off heat completely. Add 25g peanut butter.","timer_seconds":20},{"text":"Stir vigorously for 40 seconds until peanut butter melts into velvety, creamy oats.","timer_seconds":40},{"text":"Pour into a bowl and let settle for 1 minute before topping.","timer_seconds":60},{"text":"Sprinkle 25g toasted granola clusters over the warm oats for hearty texture.","timer_seconds":20}]'::jsonb, '{"kcal":598,"protein":22.9,"carbs":73.5,"fats":25.6,"fiber":10.1}'::jsonb, 44.9, 493, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=600&q=80', '🥣', 122),
(123, 'Peanut Butter Oats with Greek Yogurt Swirl', 'Continental', 'broke', ARRAY['15-min','high-protein','muscle-gain'], 8, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Place 50g rolled oats in a small pot or electric kettle.","timer_seconds":20,"tip":"⚠️ Where this goes wrong: Stirring peanut butter into rolling boiling milk causes the oil to separate and curdle. Turn off heat first, then stir in peanut butter until it melts into silky cream."},{"text":"Pour in 160ml milk (or 80ml milk + 80ml water) and a tiny pinch of salt.","timer_seconds":30},{"text":"Bring to a gentle simmer on medium-low heat, stirring with a spoon to prevent milk from scorching.","timer_seconds":120},{"text":"Cook for 2.5 minutes until oats thicken and absorb the milk.","timer_seconds":150},{"text":"Turn off heat completely. Add 25g peanut butter.","timer_seconds":20},{"text":"Stir vigorously for 40 seconds until peanut butter melts into velvety, creamy oats.","timer_seconds":40},{"text":"Pour into a bowl and let settle for 1 minute before topping.","timer_seconds":60},{"text":"Dollop 45g cold Greek yogurt in the center and swirl into the warm oats for a protein boost.","timer_seconds":30}]'::jsonb, '{"kcal":529,"protein":24.4,"carbs":59,"fats":23.6,"fiber":8.1}'::jsonb, 43.4, 398, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=600&q=80', '🥣', 123),
