(126, 'Peanut Butter Oats with Melted Butter Drizzle', 'Continental', 'broke', ARRAY['15-min','muscle-gain'], 8, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Place 50g rolled oats in a small pot or electric kettle.","timer_seconds":20,"tip":"⚠️ Where this goes wrong: Stirring peanut butter into rolling boiling milk causes the oil to separate and curdle. Turn off heat first, then stir in peanut butter until it melts into silky cream."},{"text":"Pour in 160ml milk (or 80ml milk + 80ml water) and a tiny pinch of salt.","timer_seconds":30},{"text":"Bring to a gentle simmer on medium-low heat, stirring with a spoon to prevent milk from scorching.","timer_seconds":120},{"text":"Cook for 2.5 minutes until oats thicken and absorb the milk.","timer_seconds":150},{"text":"Turn off heat completely. Add 25g peanut butter.","timer_seconds":20},{"text":"Stir vigorously for 40 seconds until peanut butter melts into velvety, creamy oats.","timer_seconds":40},{"text":"Pour into a bowl and let settle for 1 minute before topping.","timer_seconds":60},{"text":"Melt 8g butter over the hot oatmeal for rich, old-fashioned diner-style indulgence.","timer_seconds":20}]'::jsonb, '{"kcal":543,"protein":20.4,"carbs":57.2,"fats":27.9,"fiber":8.1}'::jsonb, 37.8, 364, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=600&q=80', '🥣', 126),
(127, 'Greek Yogurt Parfait with Crunchy Toasted Granola', 'Continental', 'broke', ARRAY['15-min'], 6, ARRAY['no-cook','hostel-friendly'], 1, '[{"text":"Take a clean tall glass or broad bowl.","tip":"⚠️ Where this goes wrong: Assembling the parfait hours before eating turns crispy granola soggy and chewy. Keep granola separate and layer on immediately before eating."},{"text":"Spoon 60g chilled, thick Greek yogurt into the base as the first layer.","timer_seconds":20},{"text":"Slice 1/2 banana into thin coins and place half the slices over the yogurt.","timer_seconds":30},{"text":"Sprinkle 20g crunchy granola evenly across the fruit layer.","timer_seconds":20},{"text":"Spoon remaining 60g Greek yogurt on top to form the second layer.","timer_seconds":20},{"text":"Finish with remaining banana slices and 15g granola.","timer_seconds":20},{"text":"Heap an extra generous 25g golden toasted granola clusters on top for mega crunch."}]'::jsonb, '{"kcal":431,"protein":17.3,"carbs":55.2,"fats":16.4,"fiber":6.1}'::jsonb, 58.5, 320, 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=600&q=80', '🍨', 127),
