(133, 'Greek Yogurt Parfait with Creamy Curd Layer', 'Continental', 'broke', ARRAY['15-min','fat-loss'], 6, ARRAY['no-cook','hostel-friendly'], 1, '[{"text":"Take a clean tall glass or broad bowl.","tip":"⚠️ Where this goes wrong: Assembling the parfait hours before eating turns crispy granola soggy and chewy. Keep granola separate and layer on immediately before eating."},{"text":"Spoon 60g chilled, thick Greek yogurt into the base as the first layer.","timer_seconds":20},{"text":"Slice 1/2 banana into thin coins and place half the slices over the yogurt.","timer_seconds":30},{"text":"Sprinkle 20g crunchy granola evenly across the fruit layer.","timer_seconds":20},{"text":"Spoon remaining 60g Greek yogurt on top to form the second layer.","timer_seconds":20},{"text":"Finish with remaining banana slices and 15g granola.","timer_seconds":20},{"text":"Whisk 40g fresh curd with honey and fold between fruit layers for lighter tang.","timer_seconds":30}]'::jsonb, '{"kcal":342,"protein":16.3,"carbs":40.8,"fats":13.3,"fiber":4.1}'::jsonb, 50.4, 355, 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=600&q=80', '🍨', 133),
(134, 'Avocado Sourdough Toast with Sunny-Side Fried Egg', 'Continental', 'balanced', ARRAY['15-min'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Heat a dry skillet or pan on medium induction heat (600W) for 1 minute.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Mashing warm avocado or spreading it on steaming soft bread makes toast limp and wet. Toast bread until rock-crisp, let steam vent 30s, then spread."},{"text":"Spread 8g butter on both sides of 1 thick slice of artisan sourdough bread.","timer_seconds":30},{"text":"Toast in the pan for 2 minutes per side until golden brown and audibly crispy.","timer_seconds":240},{"text":"Cut 1/2 ripe avocado, scoop flesh into a small bowl, add 1 tsp lemon juice, 1/4 tsp salt, and black pepper.","timer_seconds":45},{"text":"Mash with a fork to a chunky, spreadable texture.","timer_seconds":30},{"text":"Generously spread seasoned avocado over the crispy sourdough toast from edge to edge.","timer_seconds":30},{"text":"Fry 1 egg in butter for 2.5 minutes until whites set and yolk is runny; place atop avocado.","timer_seconds":150}]'::jsonb, '{"kcal":463,"protein":14.2,"carbs":42.7,"fats":27.6,"fiber":7.7}'::jsonb, 83.4, 348, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=600&q=80', '🥑', 134),
(135, 'Avocado Sourdough Toast with Soft Poached Egg & Chilli Flakes', 'Continental', 'balanced', ARRAY['15-min'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Heat a dry skillet or pan on medium induction heat (600W) for 1 minute.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Mashing warm avocado or spreading it on steaming soft bread makes toast limp and wet. Toast bread until rock-crisp, let steam vent 30s, then spread."},{"text":"Spread 8g butter on both sides of 1 thick slice of artisan sourdough bread.","timer_seconds":30},{"text":"Toast in the pan for 2 minutes per side until golden brown and audibly crispy.","timer_seconds":240},{"text":"Cut 1/2 ripe avocado, scoop flesh into a small bowl, add 1 tsp lemon juice, 1/4 tsp salt, and black pepper.","timer_seconds":45},{"text":"Mash with a fork to a chunky, spreadable texture.","timer_seconds":30},{"text":"Generously spread seasoned avocado over the crispy sourdough toast from edge to edge.","timer_seconds":30},{"text":"Gently poach 1 egg in simmering water for 3 minutes, place on toast, sprinkle crushed chilli flakes.","timer_seconds":180}]'::jsonb, '{"kcal":430,"protein":14.3,"carbs":43.2,"fats":23.7,"fiber":8}'::jsonb, 81, 382, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=600&q=80', '🥑', 135),
