(139, 'Avocado Sourdough Toast with Melting Cheddar Slice', 'Continental', 'balanced', ARRAY['15-min'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Heat a dry skillet or pan on medium induction heat (600W) for 1 minute.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Mashing warm avocado or spreading it on steaming soft bread makes toast limp and wet. Toast bread until rock-crisp, let steam vent 30s, then spread."},{"text":"Spread 8g butter on both sides of 1 thick slice of artisan sourdough bread.","timer_seconds":30},{"text":"Toast in the pan for 2 minutes per side until golden brown and audibly crispy.","timer_seconds":240},{"text":"Cut 1/2 ripe avocado, scoop flesh into a small bowl, add 1 tsp lemon juice, 1/4 tsp salt, and black pepper.","timer_seconds":45},{"text":"Mash with a fork to a chunky, spreadable texture.","timer_seconds":30},{"text":"Generously spread seasoned avocado over the crispy sourdough toast from edge to edge.","timer_seconds":30},{"text":"Place 1 cheese slice over avocado and cover pan for 45 seconds until velvety and melted.","timer_seconds":45}]'::jsonb, '{"kcal":420,"protein":11.8,"carbs":42.8,"fats":24.1,"fiber":7.7}'::jsonb, 83, 406, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=600&q=80', '🥑', 139),
(140, 'Avocado Sourdough Toast with Cherry Tomatoes & Basil', 'Continental', 'balanced', ARRAY['15-min'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Heat a dry skillet or pan on medium induction heat (600W) for 1 minute.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Mashing warm avocado or spreading it on steaming soft bread makes toast limp and wet. Toast bread until rock-crisp, let steam vent 30s, then spread."},{"text":"Spread 8g butter on both sides of 1 thick slice of artisan sourdough bread.","timer_seconds":30},{"text":"Toast in the pan for 2 minutes per side until golden brown and audibly crispy.","timer_seconds":240},{"text":"Cut 1/2 ripe avocado, scoop flesh into a small bowl, add 1 tsp lemon juice, 1/4 tsp salt, and black pepper.","timer_seconds":45},{"text":"Mash with a fork to a chunky, spreadable texture.","timer_seconds":30},{"text":"Generously spread seasoned avocado over the crispy sourdough toast from edge to edge.","timer_seconds":30},{"text":"Slice 40g tomatoes, toss with a touch of oil and salt, scatter across the green avocado.","timer_seconds":45}]'::jsonb, '{"kcal":362,"protein":8.2,"carbs":43.8,"fats":18.7,"fiber":8.2}'::jsonb, 74.2, 324, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=600&q=80', '🥑', 140),
(141, 'Acai Superfood Bowl with Dragon Fruit & Chia Crunch', 'Continental', 'hifi', ARRAY['15-min'], 8, ARRAY['mixer','no-cook','hostel-friendly'], 1, '[{"text":"Peel 1 ripe banana, slice into chunks, and place in freezer for 20 minutes (or use pre-frozen banana slices).","tip":"⚠️ Where this goes wrong: Adding too much liquid turns your smoothie bowl into watery soup. Add only a tiny splash of milk; pulse and tamp down until it churns like thick gelato."},{"text":"In a mixer or blender jar, add 85g acai puree and the cold banana chunks.","timer_seconds":20},{"text":"Add 30ml chilled milk or water to help the blender blades catch.","timer_seconds":15},{"text":"Pulse in 10-second bursts, stopping to scrape down sides, until thick and frosty like sorbet.","timer_seconds":60},{"text":"Spoon the frosty purple acai base into a chilled bowl and smooth with a spoon.","timer_seconds":30},{"text":"Artfully arrange sliced dragon fruit and crunchy granola down the sides.","timer_seconds":45},{"text":"Cut an extra 40g dragon fruit into cubes, arrange in a row across the bowl with seeds.","timer_seconds":60}]'::jsonb, '{"kcal":374,"protein":7.2,"carbs":65.5,"fats":10.3,"fiber":11.8}'::jsonb, 201.6, 615, 'https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&w=600&q=80', '🫐', 141),
(142, 'Acai Superfood Bowl with Sliced Banana & Crunchy Granola', 'Continental', 'hifi', ARRAY['15-min','muscle-gain'], 8, ARRAY['mixer','no-cook','hostel-friendly'], 1, '[{"text":"Peel 1 ripe banana, slice into chunks, and place in freezer for 20 minutes (or use pre-frozen banana slices).","tip":"⚠️ Where this goes wrong: Adding too much liquid turns your smoothie bowl into watery soup. Add only a tiny splash of milk; pulse and tamp down until it churns like thick gelato."},{"text":"In a mixer or blender jar, add 85g acai puree and the cold banana chunks.","timer_seconds":20},{"text":"Add 30ml chilled milk or water to help the blender blades catch.","timer_seconds":15},{"text":"Pulse in 10-second bursts, stopping to scrape down sides, until thick and frosty like sorbet.","timer_seconds":60},{"text":"Spoon the frosty purple acai base into a chilled bowl and smooth with a spoon.","timer_seconds":30},{"text":"Artfully arrange sliced dragon fruit and crunchy granola down the sides.","timer_seconds":45},{"text":"Fan 1/2 sliced banana down one side and heap 25g crunchy granola down the other.","timer_seconds":45}]'::jsonb, '{"kcal":486,"protein":9.3,"carbs":83.3,"fats":14.4,"fiber":13}'::jsonb, 188.4, 615, 'https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&w=600&q=80', '🫐', 142),
(143, 'Acai Superfood Bowl with Peanut Butter Swirl', 'Continental', 'hifi', ARRAY['15-min'], 8, ARRAY['mixer','no-cook','hostel-friendly'], 1, '[{"text":"Peel 1 ripe banana, slice into chunks, and place in freezer for 20 minutes (or use pre-frozen banana slices).","tip":"⚠️ Where this goes wrong: Adding too much liquid turns your smoothie bowl into watery soup. Add only a tiny splash of milk; pulse and tamp down until it churns like thick gelato."},{"text":"In a mixer or blender jar, add 85g acai puree and the cold banana chunks.","timer_seconds":20},{"text":"Add 30ml chilled milk or water to help the blender blades catch.","timer_seconds":15},{"text":"Pulse in 10-second bursts, stopping to scrape down sides, until thick and frosty like sorbet.","timer_seconds":60},{"text":"Spoon the frosty purple acai base into a chilled bowl and smooth with a spoon.","timer_seconds":30},{"text":"Artfully arrange sliced dragon fruit and crunchy granola down the sides.","timer_seconds":45},{"text":"Warm 15g creamy peanut butter, then drizzle artistic ribbons over the frosty purple acai.","timer_seconds":30}]'::jsonb, '{"kcal":417,"protein":10,"carbs":58.6,"fats":17.4,"fiber":10.6}'::jsonb, 179.1, 755, 'https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&w=600&q=80', '🫐', 143),
(144, 'Acai Superfood Bowl with Greek Yogurt Cloud', 'Continental', 'hifi', ARRAY['15-min'], 8, ARRAY['mixer','no-cook','hostel-friendly'], 1, '[{"text":"Peel 1 ripe banana, slice into chunks, and place in freezer for 20 minutes (or use pre-frozen banana slices).","tip":"⚠️ Where this goes wrong: Adding too much liquid turns your smoothie bowl into watery soup. Add only a tiny splash of milk; pulse and tamp down until it churns like thick gelato."},{"text":"In a mixer or blender jar, add 85g acai puree and the cold banana chunks.","timer_seconds":20},{"text":"Add 30ml chilled milk or water to help the blender blades catch.","timer_seconds":15},{"text":"Pulse in 10-second bursts, stopping to scrape down sides, until thick and frosty like sorbet.","timer_seconds":60},{"text":"Spoon the frosty purple acai base into a chilled bowl and smooth with a spoon.","timer_seconds":30},{"text":"Artfully arrange sliced dragon fruit and crunchy granola down the sides.","timer_seconds":45},{"text":"Spoon 40g thick Greek yogurt alongside the acai for a high-protein marbled swirl.","timer_seconds":20}]'::jsonb, '{"kcal":367,"protein":9.9,"carbs":57.2,"fats":11.9,"fiber":9.7}'::jsonb, 182.1, 705, 'https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&w=600&q=80', '🫐', 144),
(145, 'Acai Superfood Bowl with Roasted Peanuts & Seeds', 'Continental', 'hifi', ARRAY['15-min'], 8, ARRAY['mixer','no-cook','hostel-friendly'], 1, '[{"text":"Peel 1 ripe banana, slice into chunks, and place in freezer for 20 minutes (or use pre-frozen banana slices).","tip":"⚠️ Where this goes wrong: Adding too much liquid turns your smoothie bowl into watery soup. Add only a tiny splash of milk; pulse and tamp down until it churns like thick gelato."},{"text":"In a mixer or blender jar, add 85g acai puree and the cold banana chunks.","timer_seconds":20},{"text":"Add 30ml chilled milk or water to help the blender blades catch.","timer_seconds":15},{"text":"Pulse in 10-second bursts, stopping to scrape down sides, until thick and frosty like sorbet.","timer_seconds":60},{"text":"Spoon the frosty purple acai base into a chilled bowl and smooth with a spoon.","timer_seconds":30},{"text":"Artfully arrange sliced dragon fruit and crunchy granola down the sides.","timer_seconds":45},{"text":"Scatter 20g toasted peanuts over the bowl for rich nutty crunch against the cold fruit.","timer_seconds":20}]'::jsonb, '{"kcal":442,"protein":11.4,"carbs":58.8,"fats":19.8,"fiber":11.4}'::jsonb, 177.1, 655, 'https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&w=600&q=80', '🫐', 145),
(146, 'Acai Superfood Bowl with Diced Fresh Fruits', 'Continental', 'hifi', ARRAY['15-min'], 8, ARRAY['mixer','no-cook','hostel-friendly'], 1, '[{"text":"Peel 1 ripe banana, slice into chunks, and place in freezer for 20 minutes (or use pre-frozen banana slices).","tip":"⚠️ Where this goes wrong: Adding too much liquid turns your smoothie bowl into watery soup. Add only a tiny splash of milk; pulse and tamp down until it churns like thick gelato."},{"text":"In a mixer or blender jar, add 85g acai puree and the cold banana chunks.","timer_seconds":20},{"text":"Add 30ml chilled milk or water to help the blender blades catch.","timer_seconds":15},{"text":"Pulse in 10-second bursts, stopping to scrape down sides, until thick and frosty like sorbet.","timer_seconds":60},{"text":"Spoon the frosty purple acai base into a chilled bowl and smooth with a spoon.","timer_seconds":30},{"text":"Artfully arrange sliced dragon fruit and crunchy granola down the sides.","timer_seconds":45},{"text":"Arrange diced dragon fruit and sweet banana coins across the surface for a cafe look.","timer_seconds":60}]'::jsonb, '{"kcal":403,"protein":7.4,"carbs":73.6,"fats":10.3,"fiber":12.3}'::jsonb, 195.9, 615, 'https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&w=600&q=80', '🫐', 146),
(147, 'Acai Superfood Bowl with Chilled Coconut Milk Layer', 'Continental', 'hifi', ARRAY['15-min'], 8, ARRAY['mixer','no-cook','hostel-friendly'], 1, '[{"text":"Peel 1 ripe banana, slice into chunks, and place in freezer for 20 minutes (or use pre-frozen banana slices).","tip":"⚠️ Where this goes wrong: Adding too much liquid turns your smoothie bowl into watery soup. Add only a tiny splash of milk; pulse and tamp down until it churns like thick gelato."},{"text":"In a mixer or blender jar, add 85g acai puree and the cold banana chunks.","timer_seconds":20},{"text":"Add 30ml chilled milk or water to help the blender blades catch.","timer_seconds":15},{"text":"Pulse in 10-second bursts, stopping to scrape down sides, until thick and frosty like sorbet.","timer_seconds":60},{"text":"Spoon the frosty purple acai base into a chilled bowl and smooth with a spoon.","timer_seconds":30},{"text":"Artfully arrange sliced dragon fruit and crunchy granola down the sides.","timer_seconds":45},{"text":"Drizzle 30ml chilled milk around the perimeter for a creamy white halo.","timer_seconds":20}]'::jsonb, '{"kcal":347,"protein":7.2,"carbs":57,"fats":10.9,"fiber":9.7}'::jsonb, 175.1, 648, 'https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&w=600&q=80', '🫐', 147),
(148, 'Hummus Pita Wrap with Spiced Paneer Cubes', 'Middle Eastern', 'broke', ARRAY['15-min','fat-loss'], 10, ARRAY['1-pan','no-cook','hostel-friendly'], 1, '[{"text":"In a small bowl, whisk 50g thick curd with 1 tsp oil, 1 minced garlic clove, squeeze of lemon, and pinch of salt.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Over-toasting the pita makes it stiff and brittle so it snaps when rolled. Warm it on the pan for just 30 seconds per side so it stays pliable and soft."},{"text":"Thinly slice 35g onion and 35g tomato into crescent strips."},{"text":"Warm 1 pita bread or flatbread on a dry pan for 30 seconds per side until soft and pliable.","timer_seconds":60},{"text":"Lay the warm bread flat; spread the garlic yogurt sauce down the center third.","timer_seconds":20},{"text":"Layer sliced onions, tomatoes, and herbs over the spread.","timer_seconds":30},{"text":"Roll the bottom edge up, fold sides in, roll into a tight wrap, and slice diagonally in half.","timer_seconds":30},{"text":"Toss 65g paneer cubes with 1/2 tsp garam masala, pan-sear 2 minutes, and tuck inside the wrap.","timer_seconds":120}]'::jsonb, '{"kcal":387,"protein":17.4,"carbs":27.8,"fats":23,"fiber":2.7}'::jsonb, 44.8, 401, 'https://images.unsplash.com/photo-1627308595229-7830a5c91f9f?auto=format&fit=crop&w=600&q=80', '🥙', 148),
(149, 'Hummus Pita Wrap with Seared Chicken Shawarma Strips', 'Middle Eastern', 'broke', ARRAY['15-min','high-protein','fat-loss'], 13, ARRAY['1-pan','no-cook','hostel-friendly'], 1, '[{"text":"In a small bowl, whisk 50g thick curd with 1 tsp oil, 1 minced garlic clove, squeeze of lemon, and pinch of salt.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Over-toasting the pita makes it stiff and brittle so it snaps when rolled. Warm it on the pan for just 30 seconds per side so it stays pliable and soft."},{"text":"Thinly slice 35g onion and 35g tomato into crescent strips."},{"text":"Warm 1 pita bread or flatbread on a dry pan for 30 seconds per side until soft and pliable.","timer_seconds":60},{"text":"Lay the warm bread flat; spread the garlic yogurt sauce down the center third.","timer_seconds":20},{"text":"Layer sliced onions, tomatoes, and herbs over the spread.","timer_seconds":30},{"text":"Roll the bottom edge up, fold sides in, roll into a tight wrap, and slice diagonally in half.","timer_seconds":30},{"text":"Season 110g chicken strips with garlic, cumin, and chilli; sear 4 minutes and roll inside.","timer_seconds":240}]'::jsonb, '{"kcal":380,"protein":39.8,"carbs":25.9,"fats":12.7,"fiber":2.7}'::jsonb, 54.6, 486, 'https://images.unsplash.com/photo-1627308595229-7830a5c91f9f?auto=format&fit=crop&w=600&q=80', '🥙', 149),
(150, 'Hummus Pita Wrap with Sautéed Capsicum & Onions', 'Middle Eastern', 'broke', ARRAY['15-min'], 10, ARRAY['1-pan','no-cook','hostel-friendly'], 1, '[{"text":"In a small bowl, whisk 50g thick curd with 1 tsp oil, 1 minced garlic clove, squeeze of lemon, and pinch of salt.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Over-toasting the pita makes it stiff and brittle so it snaps when rolled. Warm it on the pan for just 30 seconds per side so it stays pliable and soft."},{"text":"Thinly slice 35g onion and 35g tomato into crescent strips."},{"text":"Warm 1 pita bread or flatbread on a dry pan for 30 seconds per side until soft and pliable.","timer_seconds":60},{"text":"Lay the warm bread flat; spread the garlic yogurt sauce down the center third.","timer_seconds":20},{"text":"Layer sliced onions, tomatoes, and herbs over the spread.","timer_seconds":30},{"text":"Roll the bottom edge up, fold sides in, roll into a tight wrap, and slice diagonally in half.","timer_seconds":30},{"text":"Sauté 35g bell pepper and onion strips in 1/2 tsp oil for 2 minutes before packing into wrap.","timer_seconds":120}]'::jsonb, '{"kcal":207,"protein":6.1,"carbs":28,"fats":8.8,"fiber":3.5}'::jsonb, 21.7, 348, 'https://images.unsplash.com/photo-1627308595229-7830a5c91f9f?auto=format&fit=crop&w=600&q=80', '🥙', 150)
INSERT INTO public.recipes (id, title, cuisine, budget_tier, goals, minutes, equipment_tags, servings, steps, macros, cost_per_serving, cost_full_pack, image_url, emoji, gradient_seed) VALUES
(151, 'Hummus Pita Wrap with Sliced Boiled Egg', 'Middle Eastern', 'broke', ARRAY['15-min'], 10, ARRAY['1-pan','no-cook','hostel-friendly'], 1, '[{"text":"In a small bowl, whisk 50g thick curd with 1 tsp oil, 1 minced garlic clove, squeeze of lemon, and pinch of salt.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Over-toasting the pita makes it stiff and brittle so it snaps when rolled. Warm it on the pan for just 30 seconds per side so it stays pliable and soft."},{"text":"Thinly slice 35g onion and 35g tomato into crescent strips."},{"text":"Warm 1 pita bread or flatbread on a dry pan for 30 seconds per side until soft and pliable.","timer_seconds":60},{"text":"Lay the warm bread flat; spread the garlic yogurt sauce down the center third.","timer_seconds":20},{"text":"Layer sliced onions, tomatoes, and herbs over the spread.","timer_seconds":30},{"text":"Roll the bottom edge up, fold sides in, roll into a tight wrap, and slice diagonally in half.","timer_seconds":30},{"text":"Hard-boil 1 egg (7.5 mins), slice lengthwise, and layer inside with cracked black pepper.","timer_seconds":450}]'::jsonb, '{"kcal":270,"protein":12,"carbs":26.3,"fats":13.7,"fiber":2.7}'::jsonb, 25.9, 368, 'https://images.unsplash.com/photo-1627308595229-7830a5c91f9f?auto=format&fit=crop&w=600&q=80', '🥙', 151),
(152, 'Hummus Pita Wrap with Crispy Soya Chunks', 'Middle Eastern', 'broke', ARRAY['15-min','fat-loss'], 10, ARRAY['1-pan','no-cook','hostel-friendly'], 1, '[{"text":"In a small bowl, whisk 50g thick curd with 1 tsp oil, 1 minced garlic clove, squeeze of lemon, and pinch of salt.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Over-toasting the pita makes it stiff and brittle so it snaps when rolled. Warm it on the pan for just 30 seconds per side so it stays pliable and soft."},{"text":"Thinly slice 35g onion and 35g tomato into crescent strips."},{"text":"Warm 1 pita bread or flatbread on a dry pan for 30 seconds per side until soft and pliable.","timer_seconds":60},{"text":"Lay the warm bread flat; spread the garlic yogurt sauce down the center third.","timer_seconds":20},{"text":"Layer sliced onions, tomatoes, and herbs over the spread.","timer_seconds":30},{"text":"Roll the bottom edge up, fold sides in, roll into a tight wrap, and slice diagonally in half.","timer_seconds":30},{"text":"Soak 35g soya chunks, squeeze dry, toss with spices, crisp in a pan, and roll up.","timer_seconds":240}]'::jsonb, '{"kcal":319,"protein":23.9,"carbs":37.4,"fats":8.9,"fiber":7.3}'::jsonb, 25.1, 361, 'https://images.unsplash.com/photo-1627308595229-7830a5c91f9f?auto=format&fit=crop&w=600&q=80', '🥙', 152),
(153, 'Hummus Pita Wrap with Fresh Tomato & Herb Salad', 'Middle Eastern', 'broke', ARRAY['15-min'], 10, ARRAY['1-pan','no-cook','hostel-friendly'], 1, '[{"text":"In a small bowl, whisk 50g thick curd with 1 tsp oil, 1 minced garlic clove, squeeze of lemon, and pinch of salt.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Over-toasting the pita makes it stiff and brittle so it snaps when rolled. Warm it on the pan for just 30 seconds per side so it stays pliable and soft."},{"text":"Thinly slice 35g onion and 35g tomato into crescent strips."},{"text":"Warm 1 pita bread or flatbread on a dry pan for 30 seconds per side until soft and pliable.","timer_seconds":60},{"text":"Lay the warm bread flat; spread the garlic yogurt sauce down the center third.","timer_seconds":20},{"text":"Layer sliced onions, tomatoes, and herbs over the spread.","timer_seconds":30},{"text":"Roll the bottom edge up, fold sides in, roll into a tight wrap, and slice diagonally in half.","timer_seconds":30},{"text":"Toss 50g diced tomatoes with fresh coriander and lemon juice for a juicy crunch inside the wrap.","timer_seconds":60}]'::jsonb, '{"kcal":209,"protein":6.3,"carbs":28.1,"fats":8.9,"fiber":3.5}'::jsonb, 20.1, 331, 'https://images.unsplash.com/photo-1627308595229-7830a5c91f9f?auto=format&fit=crop&w=600&q=80', '🥙', 153),
(154, 'Hummus Pita Wrap with Melting Cheese Slice', 'Middle Eastern', 'broke', ARRAY['15-min'], 10, ARRAY['1-pan','no-cook','hostel-friendly'], 1, '[{"text":"In a small bowl, whisk 50g thick curd with 1 tsp oil, 1 minced garlic clove, squeeze of lemon, and pinch of salt.","timer_seconds":60,"tip":"⚠️ Where this goes wrong: Over-toasting the pita makes it stiff and brittle so it snaps when rolled. Warm it on the pan for just 30 seconds per side so it stays pliable and soft."},{"text":"Thinly slice 35g onion and 35g tomato into crescent strips."},{"text":"Warm 1 pita bread or flatbread on a dry pan for 30 seconds per side until soft and pliable.","timer_seconds":60},{"text":"Lay the warm bread flat; spread the garlic yogurt sauce down the center third.","timer_seconds":20},{"text":"Layer sliced onions, tomatoes, and herbs over the spread.","timer_seconds":30},{"text":"Roll the bottom edge up, fold sides in, roll into a tight wrap, and slice diagonally in half.","timer_seconds":30},{"text":"Place 1 cheese slice on the hot pita so it melts before rolling up.","timer_seconds":30}]'::jsonb, '{"kcal":263,"protein":9.7,"carbs":26.4,"fats":14.2,"fiber":2.7}'::jsonb, 28.2, 426, 'https://images.unsplash.com/photo-1627308595229-7830a5c91f9f?auto=format&fit=crop&w=600&q=80', '🥙', 154)
